#include <WiFi.h>
#include <WebServer.h>
#include <ArduinoJson.h>
#include <Wire.h>
#include <Adafruit_MCP4725.h>
#include <EEPROM.h>
#include <Update.h>
#include "esp_timer.h"
#include "soc/gpio_struct.h"

// ============================================
// HOTSPOT CREDENTIALS
// ============================================
const char* ssid     = "CBR250RR-RPM-Monitor";
const char* password = "12345678";

WebServer server(80);

// ============================================
// EEPROM
// ============================================
#define EEPROM_SIZE      512
#define EEPROM_START_ADDR 0
#define CONFIG_VERSION   "V28"  // v28: QS tulis ulang dari nol, polling instan NPN INPUT_PULLUP

// ============================================
// PIN DEFINITIONS
// ============================================
const int pulserPin          = 18;
const int ignitionPin        = 19;
const int clutchSensorPin    = 32;
const int physicalButtonPin  = 27;
const int quickShifterUpPin  = 25;
const int quickShifterDownPin= 26;

// ============================================
// MUTEX — FIX #1: Proteksi semua shared variables antar Core 0 dan Core 1
// Setiap variabel yang dibaca Core 1 DAN ditulis Core 0 harus dibungkus mutex
// ============================================
portMUX_TYPE dataMux = portMUX_INITIALIZER_UNLOCKED;

// ============================================
// RPM MEASUREMENT — Dual Filter + Spike Rejection
// ============================================
volatile unsigned long pulseCount      = 0;
unsigned long lastCalculationTime      = 0;
unsigned long lastPulseCount           = 0;

float displayRPM                       = 0;
float controlRPM                       = 0;
float currentRPM                       = 0;
float maxRPM                           = 0;

// FIX #2: isrSafeRPM harus volatile karena dibaca di ISR
volatile float isrSafeRPM              = 0;

float PULSES_PER_REVOLUTION            = 13.3f;
// CATATAN: Verifikasi nilai PPR sesuai jumlah gigi rotor pulser motor kamu
// Jika RPM terbaca tidak akurat, sesuaikan nilai ini

const unsigned long CALCULATION_INTERVAL = 50;
const float DISPLAY_FILTER_ALPHA       = 0.7f;
const float CONTROL_FILTER_ALPHA       = 0.3f;

const float SPIKE_MAX_RISE             = 3000.0f;
const float SPIKE_MAX_DROP             = 4000.0f;
float       lastValidRPM               = 0;

const int   RPM_CONFIRM_COUNT          = 3;
int         pitLimiterConfirmCounter   = 0;
int         launchConfirmCounter       = 0;

// ============================================
// LAUNCH CONTROL
// ============================================
bool          launchControlEnabled     = false;
float         launchControlRPMLimit    = 8000.0f;
bool          launchControlActive      = false;
unsigned long clutchReleaseTime        = 0;
bool          clutchEngaged            = false;
bool          lastClutchState          = false;
unsigned long launchControlDelay       = 3000;
bool          launchControlDelayActive = false;

// ============================================
// PIT LIMITER
// ============================================
bool  pitLimiterEnabled  = false;
float pitLimiterRPMLimit = 6000.0f;
bool  pitLimiterActive   = false;

float         pitCutRatio       = 75.0f;
unsigned long pitPwmPeriod      = 38;

// ============================================
// BACKFIRE
// ============================================
bool          backfireEnabled   = true;
bool          backfireActive    = false;
float         backfireRPMLimit  = 4000.0f;
unsigned long lastBackfireTime  = 0;
const unsigned long BACKFIRE_COOLDOWN = 500;
float         prevRPMForBackfire = 0;

// ============================================
// IGNITION CUT
// ============================================
bool          ignitionCutActive    = false;
bool          softCutActive        = false;
bool          hardCutActive        = false;

float         SOFT_CUT_RANGE       = 300.0f;

const unsigned long SOFT_PERIOD_PULSES = 24;   // v29: siklus soft cut dalam PULSE (~1.8 putaran)
unsigned long softCutPeriodStart    = 0;
bool          softCutInOffPhase     = false;

const float   HARD_CUT_HYSTERESIS  = 200.0f;
bool          hardCutLatch          = false;

unsigned long hardCutStartTime      = 0;
const unsigned long HARD_CUT_SAFETY_MS = 3000;

// ============================================
// QUICK SHIFTER — Tulis ulang v28
// Sensor: NJK-5002C NPN NO + INPUT_PULLUP
//   Idle  = pin HIGH (pullup)
//   Aktif = pin LOW  (sensor tarik ke GND)
// Trigger: pin LOW saat QS_IDLE → langsung CUTTING (instan, tanpa debounce delay)
// Cooldown: setelah cutting selesai, sensor dikunci selama quickShifterCooldownTime ms
// ============================================
bool          quickShifterEnabled           = false;
bool          quickShifterUpEnabled         = true;
bool          quickShifterDownEnabled       = true;
unsigned long quickShifterCutTime3000       = 60;
unsigned long quickShifterCutTime6000       = 50;
unsigned long quickShifterCutTime9000       = 40;
unsigned long quickShifterCutTime12000      = 30;
unsigned long quickShifterDownshiftDuration = 100;
unsigned long quickShifterCooldownTime      = 150;
int           quickShifterMinRPM            = 0;

// State machine — hanya diakses Core 1
enum QSState { QS_IDLE, QS_CUTTING, QS_COOLDOWN };
QSState       qsState         = QS_IDLE;
bool          qsIsUpshift     = true;
unsigned long qsCutStartMs    = 0;
unsigned long qsCooldownStart = 0;
bool          qsDacWritten    = false;

// ============================================
// AUTO WARM UP
// ============================================
bool          autoWarmUpEnabled    = false;
float         warmUpRPMLimit       = 3000.0f;
unsigned long warmUpStartTime      = 0;
unsigned long warmUpDuration       = 180000;
bool          warmUpActive         = false;
unsigned long warmUpLastCycleTime  = 0;
bool          warmUpHighPhase      = false;
unsigned long warmUpRiseTime       = 70;
unsigned long warmUpIdleTime       = 1000;

// ============================================
// TIMING KUDA
// ============================================
bool          timingKudaEnabled      = false;
bool          timingKudaActive       = false;
float         timingKudaRPMLimit     = 1800.0f;
unsigned long timingKudaLastCut      = 0;
unsigned long timingKudaCutDuration  = 100;
unsigned long timingKudaCutInterval  = 500;

// ============================================
// DAC (MCP4725)
// ============================================
Adafruit_MCP4725 dac1;
Adafruit_MCP4725 dac2;

const float idleAP1    = 0.488f;
const float idleAP2    = 0.234f;
const float throttleAP1= 1.268f;
const float throttleAP2= 0.624f;

const uint16_t DAC_IDLE_AP1    = (uint16_t)((idleAP1    / 3.3f) * 4095);
const uint16_t DAC_IDLE_AP2    = (uint16_t)((idleAP2    / 3.3f) * 4095);
const uint16_t DAC_WARM_UP_AP1 = (uint16_t)((throttleAP1/ 3.3f) * 4095);
const uint16_t DAC_WARM_UP_AP2 = (uint16_t)((throttleAP2/ 3.3f) * 4095);

// ============================================
// PHYSICAL BUTTON
// ============================================
unsigned long buttonPressTime     = 0;
unsigned long buttonReleaseTime   = 0;
bool          buttonPressed       = false;
bool          buttonLongPressActive = false;
int           buttonClickCount    = 0;
unsigned long lastClickTime       = 0;
const unsigned long DEBOUNCE_DELAY    = 100;
const unsigned long DOUBLE_CLICK_TIME = 700;
const unsigned long LONG_PRESS_TIME   = 2000;

// ============================================
// HOTSPOT AUTO OFF
// v14 FIX: Ganti konsep activity-based ke deadline absolute.
// Bug lama: hotspotLastActivity di-reset setiap poll /rpm-data 100ms
//           → rem = timeoutDuration - (now - lastActivity) selalu penuh → tidak countdown.
// Fix: hotspotDeadline = millis() saat timer mulai.
//      Sisa waktu = hotspotDeadline - millis() (langsung turun tiap ms).
//      +1 min = hotspotDeadline += 60000 (dari detik terakhir, bukan restart).
// ============================================
bool          hotspotAutoOffEnabled   = true;
unsigned long hotspotDeadline         = 0;   // absolute timestamp kapan wifi mati
bool          hotspotActive           = true;
bool          pendingDisconnect       = false;

// ============================================
// CONFIG STRUCT
// ============================================
struct SystemConfig {
  char version[4];
  bool          launchControlEnabled;
  float         launchControlRPMLimit;
  unsigned long launchControlDelay;
  bool          pitLimiterEnabled;
  float         pitLimiterRPMLimit;
  float         pitCutRatio;
  unsigned long pitPwmPeriod;
  bool          backfireEnabled;
  float         backfireRPMLimit;
  bool          quickShifterEnabled;
  bool          quickShifterUpEnabled;
  bool          quickShifterDownEnabled;
  int           quickShifterMinRPM;
  unsigned long quickShifterCutTime3000;
  unsigned long quickShifterCutTime6000;
  unsigned long quickShifterCutTime9000;
  unsigned long quickShifterCutTime12000;
  unsigned long quickShifterDownshiftDuration;
  unsigned long quickShifterCooldownTime;
  bool          autoWarmUpEnabled;
  float         warmUpRPMLimit;
  unsigned long warmUpDuration;
  unsigned long warmUpRiseTime;
  unsigned long warmUpIdleTime;
  bool          timingKudaEnabled;
  float         timingKudaRPMLimit;
  unsigned long timingKudaCutDuration;
  unsigned long timingKudaCutInterval;
  bool          hotspotAutoOffEnabled;
  float         softCutRange;
};

SystemConfig config;

// ============================================
// FORWARD DECLARATIONS
// ============================================
// QS menggunakan polling-based debounce, tidak pakai ISR
void wifiTask(void* pvParameters);
void motorTask(void* pvParameters);
void handleTestQSUp();
void handleTestQSDown();
void handleOTAUpdate();
void handleOTAUpload();
void applyConfig();
void saveConfig();
void loadConfig();
void handleQuickShifter();
void calculateRPM();
void restartHotspot();
void handleSetQuickShifterCooldown();

// ============================================
// HTML PAGE
// ============================================
const char* htmlPage = R"rawliteral(
<!DOCTYPE HTML>
<html lang="id">
<head>
<title>CBR250RR Control System</title>
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1">
<meta charset="UTF-8">
<style>
:root {
  --red:     #e8000d;
  --red-dim: #8b0008;
  --orange:  #ff6600;
  --green:   #00e676;
  --yellow:  #ffd600;
  --bg:      #0b0b0f;
  --bg2:     #13131a;
  --bg3:     #1c1c28;
  --border:  #2a2a3a;
  --text:    #e0e0ee;
  --muted:   #6a6a88;
  --font:    -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --mono:    'Courier New', 'Lucida Console', monospace;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  min-height: 100vh;
}
body {
  padding: 12px;
  background-image:
    repeating-linear-gradient(0deg,   transparent, transparent 39px, rgba(255,255,255,0.02) 40px),
    repeating-linear-gradient(90deg,  transparent, transparent 39px, rgba(255,255,255,0.02) 40px);
}

/* ── TOP BAR ── */
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 16px; margin-bottom: 12px;
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: 8px;
  border-top: 3px solid var(--red);
}
.topbar-logo {
  font-family: var(--mono); font-size: 1em; font-weight: bold;
  color: var(--red); letter-spacing: 2px; text-transform: uppercase;
}
.topbar-ver {
  font-size: 0.72em; color: var(--muted); letter-spacing: 1px;
}

/* ── RPM PANEL ── */
.rpm-panel {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px 16px 14px;
  margin-bottom: 12px;
  position: relative;
  overflow: hidden;
}
.rpm-panel::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: linear-gradient(90deg, var(--red), var(--orange), var(--red));
}
.rpm-label {
  font-size: 0.68em; letter-spacing: 3px; text-transform: uppercase;
  color: var(--muted); margin-bottom: 4px; text-align: center;
}
.rpm-display {
  font-family: var(--mono);
  font-size: 4.5em; font-weight: bold;
  color: var(--red);
  text-align: center; line-height: 1;
  text-shadow: 0 0 20px rgba(232,0,13,0.5);
  letter-spacing: -2px;
}
.rpm-unit {
  font-size: 0.8em; color: var(--muted);
  text-align: center; letter-spacing: 4px;
  margin-top: 2px; margin-bottom: 12px;
}
.rpm-row {
  display: flex; gap: 8px;
}
.rpm-sub {
  flex: 1; background: var(--bg3); border-radius: 6px;
  padding: 8px 10px; text-align: center;
}
.rpm-sub-label { font-size: 0.6em; color: var(--muted); letter-spacing: 2px; text-transform: uppercase; }
.rpm-sub-val {
  font-family: var(--mono); font-size: 1.2em; font-weight: bold;
  color: var(--text);
}

/* ── STATUS BAR ── */
.status-bar {
  display: flex; gap: 6px; flex-wrap: wrap;
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: 8px; padding: 10px 14px;
  margin-bottom: 12px; font-size: 0.78em;
}
.status-item { display: flex; align-items: center; gap: 5px; }
.status-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--green); display: inline-block;
}
.status-key { color: var(--muted); }
.status-val { font-weight: 600; font-family: var(--mono); }

/* ── HOTSPOT TIMER ── */
.hotspot-panel {
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: 8px; padding: 12px 16px;
  margin-bottom: 12px;
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 8px;
}
.hotspot-left { display: flex; align-items: center; gap: 10px; }
.hotspot-icon { font-size: 1.2em; }
.hotspot-label { font-size: 0.68em; letter-spacing: 2px; text-transform: uppercase; color: var(--muted); }
#hotspotTimeout {
  font-family: var(--mono); font-size: 1.6em; font-weight: bold;
  color: var(--orange);
}
.hotspot-note { font-size: 0.65em; color: var(--muted); }
.hotspot-btns { display: flex; gap: 6px; }

/* ── BUTTON INFO ── */
.btn-info {
  background: var(--bg2); border: 1px solid var(--border);
  border-left: 3px solid var(--orange);
  border-radius: 8px; padding: 10px 14px;
  margin-bottom: 12px; font-size: 0.75em; color: var(--muted);
  line-height: 1.6;
}
.btn-info strong { color: var(--text); }

/* ── SECTION TITLE ── */
.section-title {
  font-size: 0.65em; letter-spacing: 3px; text-transform: uppercase;
  color: var(--muted); padding: 6px 4px; margin-bottom: 6px;
  border-bottom: 1px solid var(--border);
}

/* ── SYSTEM CARDS ── */
.control-panel { margin-bottom: 12px; }
.system-card {
  background: var(--bg2); border: 1px solid var(--border);
  border-radius: 8px; padding: 12px 14px;
  margin-bottom: 8px; cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
  position: relative; overflow: hidden;
}
.system-card::after {
  content: '';
  position: absolute; left: 0; top: 0; bottom: 0;
  width: 3px; background: var(--border);
  transition: background 0.2s;
}
.system-card:hover { border-color: #3a3a55; background: #15151f; }
.system-card.active { border-color: var(--red-dim); }
.system-card.active::after { background: var(--red); }
.system-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.system-title { font-size: 0.92em; font-weight: 700; letter-spacing: 1px; color: var(--text); text-transform: uppercase; }
.system-status {
  font-size: 0.65em; padding: 3px 10px; border-radius: 20px;
  background: var(--bg3); color: var(--muted);
  font-weight: 600; letter-spacing: 1px; text-transform: uppercase;
  border: 1px solid var(--border);
}
.system-status.on { background: rgba(0,230,118,0.15); color: var(--green); border-color: var(--green); }
.system-status.active { background: rgba(232,0,13,0.2); color: var(--red); border-color: var(--red); }
.card-btns { display: flex; gap: 6px; }

/* ── BUTTONS ── */
.btn {
  padding: 8px 16px; border: none; border-radius: 5px;
  cursor: pointer; font-size: 0.78em; font-weight: 700;
  letter-spacing: 1px; text-transform: uppercase;
  transition: all 0.2s; font-family: var(--font);
}
.btn-on   { background: var(--red);    color: #fff; }
.btn-off  { background: var(--bg3);    color: var(--muted); border: 1px solid var(--border); }
.btn-settings { background: transparent; color: var(--muted); border: 1px solid var(--border); }
.btn-settings:hover { border-color: var(--orange); color: var(--orange); }
.btn-reset { background: #2a1a4a; color: #bb86fc; border: 1px solid #4a2a7a; }
.btn-save  { background: rgba(0,230,118,0.15); color: var(--green); border: 1px solid var(--green); }
.btn-red   { background: var(--red); color: #fff; }
.btn-orange{ background: #2a1500; color: var(--orange); border: 1px solid var(--orange); }
.btn-purple{ background: #1a0a2a; color: #bb86fc; border: 1px solid #7b2fff; }
.btn:active { opacity: 0.8; transform: scale(0.98); }

/* ── BOTTOM ROW ── */
.bottom-row {
  display: flex; gap: 6px; justify-content: center;
  flex-wrap: wrap; margin-top: 4px;
}

/* ── MODAL ── */
.modal {
  display: none; position: fixed; z-index: 1000;
  left: 0; top: 0; width: 100%; height: 100%;
  background: rgba(0,0,0,0.75); backdrop-filter: blur(4px);
}
.modal-content {
  background: var(--bg2); margin: 4% auto;
  padding: 20px; border-radius: 12px;
  width: 93%; max-width: 480px;
  max-height: 88vh; overflow-y: auto;
  border: 1px solid var(--border);
  border-top: 3px solid var(--red);
}
.modal-content h2 {
  font-size: 1em; letter-spacing: 2px; text-transform: uppercase;
  color: var(--red); margin-bottom: 16px; padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}
.modal-content h3 {
  font-size: 0.82em; letter-spacing: 2px; text-transform: uppercase;
  color: var(--orange); margin: 12px 0 8px;
}
.close {
  float: right; font-size: 22px; color: var(--muted);
  cursor: pointer; line-height: 1; margin-top: -4px;
}
.close:hover { color: var(--red); }

/* ── INPUT GROUPS ── */
.input-group { margin: 12px 0; }
.input-group label {
  display: block; margin-bottom: 5px;
  font-size: 0.75em; font-weight: 600; letter-spacing: 1px;
  text-transform: uppercase; color: var(--muted);
}
.input-group input[type="number"],
.input-group input[type="text"] {
  width: 100%; padding: 9px 12px;
  background: var(--bg3); border: 1px solid var(--border);
  border-radius: 5px; color: var(--text);
  font-size: 1em; font-family: var(--mono);
  transition: border-color 0.2s; outline: none;
}
.input-group input:focus { border-color: var(--orange); }
.input-group small { color: var(--muted); font-size: 0.72em; margin-top: 4px; display: block; }
.checkbox-group { display: flex; align-items: center; gap: 10px; margin: 8px 0; }
.checkbox-group input { width: 16px; height: 16px; accent-color: var(--red); cursor: pointer; }
.checkbox-group label { font-size: 0.8em; color: var(--text); cursor: pointer; }
hr { border: none; border-top: 1px solid var(--border); margin: 12px 0; }

/* ── RPM RANGE (quickshifter modal) ── */
.rpm-range {
  background: var(--bg3); padding: 10px 12px; border-radius: 6px;
  margin: 8px 0; border-left: 3px solid var(--orange);
}
.rpm-range label {
  font-size: 0.72em; text-transform: uppercase; letter-spacing: 1px;
  color: var(--muted); margin-bottom: 5px;
}

/* ── PIT CALC ── */
.pit-calc {
  background: var(--bg3); border: 1px solid var(--border);
  border-radius: 8px; padding: 12px; margin: 10px 0; text-align: center;
  font-size: 0.85em;
}
.pit-calc-row { display: flex; align-items: center; justify-content: center; gap: 8px; }
.pit-on  { color: var(--green); font-weight: bold; font-family: var(--mono); font-size: 1.1em; }
.pit-off { color: var(--red);   font-weight: bold; font-family: var(--mono); font-size: 1.1em; }
.pit-guide {
  background: var(--bg3); border-left: 3px solid var(--orange);
  border-radius: 5px; padding: 10px 12px; margin: 8px 0;
  font-size: 0.78em; line-height: 1.8; color: var(--text);
}

/* ── SAVE SECTION ── */
.save-section {
  text-align: center; margin-top: 16px; padding-top: 14px;
  border-top: 1px solid var(--border);
}

/* ── TEST SECTION ── */
.test-section {
  text-align: center; margin-top: 12px; padding-top: 12px;
  border-top: 1px solid var(--border);
}
.test-note { font-size: 0.72em; color: var(--muted); margin-bottom: 8px; }

/* ── SCROLLBAR ── */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

/* ── PULSER SCOPE ── */
.scope-wrap { background:#030d08; border:1px solid #0d3a22; border-radius:8px; overflow:hidden; }
#scopeCanvas { width:100%; height:240px; display:block; }
.scope-stats { display:grid; grid-template-columns:repeat(3,1fr); gap:6px; margin-top:10px; }
.scope-stat  { background:var(--bg3); border:1px solid var(--border); border-radius:6px; padding:6px 4px; text-align:center; }
.scope-stat .k { font-size:0.58em; color:var(--muted); letter-spacing:1px; text-transform:uppercase; }
.scope-stat .v { font-family:var(--mono); font-size:0.92em; color:var(--green); margin-top:2px; }
.scope-ctrl  { display:flex; gap:6px; flex-wrap:wrap; margin-top:10px; align-items:center; }
.scope-select { background:var(--bg3); color:var(--text); border:1px solid var(--border); border-radius:6px; padding:7px 8px; font-family:var(--mono); font-size:0.8em; }
.scope-legend { font-size:0.7em; color:var(--muted); line-height:1.7; margin-top:10px; }
</style>
</head>
<body>

<!-- TOP BAR -->
<div class="topbar">
  <div class="topbar-logo">&#9651; CBR250RR</div>
  <div class="topbar-ver">CONTROL SYSTEM &nbsp;|&nbsp; v29</div>
</div>

<!-- RPM PANEL -->
<div class="rpm-panel">
  <div class="rpm-label">Engine Speed</div>
  <div class="rpm-display" id="rpmValue">0</div>
  <div class="rpm-unit">RPM</div>
  <div class="rpm-row">
    <div class="rpm-sub">
      <div class="rpm-sub-label">Control RPM</div>
      <div class="rpm-sub-val" id="controlRpmValue">0</div>
    </div>
    <div class="rpm-sub">
      <div class="rpm-sub-label">Max RPM</div>
      <div class="rpm-sub-val" id="maxRpm">0</div>
    </div>
  </div>
</div>

