      <span style="color:#ffd600;">&#9632; CH1</span> sinyal pulser (rising edge terukur, lebar pulse ilustrasi) &nbsp;
      <span style="color:#00e676;">&#9632; CH2</span> ignition ON &nbsp;
      <span style="color:#ff1744;">&#9632;</span> CUT<br>
      Mode roll (scroll terus). Cut limiter berbasis pulse terlihat sebagai CH2 turun mengikuti jarak pulse CH1.
    </div>
  </div>
</div>

<script>
function startOTA() {
  const fileInput = document.getElementById('otaFile');
  const file = fileInput.files[0];
  if (!file) { alert('Pilih file .bin terlebih dahulu!'); return; }
  if (!file.name.endsWith('.bin')) { alert('File harus berformat .bin'); return; }
  if (!confirm('Upload firmware ' + file.name + ' (' + (file.size/1024).toFixed(1) + ' KB)?\n\nESP32 akan restart setelah update selesai.')) return;

  const btn = document.getElementById('otaUploadBtn');
  btn.disabled = true;
  btn.textContent = 'Uploading...';
  document.getElementById('otaProgress').style.display = 'block';
  document.getElementById('otaStatus').textContent = 'Uploading...';
  document.getElementById('otaStatus').style.color = 'var(--orange)';

  // Flag: apakah upload sudah mencapai 100%
  let uploadComplete = false;

  const xhr = new XMLHttpRequest();
  xhr.open('POST', '/ota-update', true);
  xhr.timeout = 60000;  // 60 detik timeout

  xhr.upload.onprogress = function(e) {
    if (e.lengthComputable) {
      const pct = Math.round((e.loaded / e.total) * 100);
      document.getElementById('otaProgressBar').style.width = pct + '%';
      document.getElementById('otaProgressText').textContent = pct + '%  (' + (e.loaded/1024).toFixed(1) + ' / ' + (e.total/1024).toFixed(1) + ' KB)';
      document.getElementById('otaStatus').textContent = 'Uploading... ' + pct + '%';
      if (pct >= 100) {
        uploadComplete = true;
        document.getElementById('otaStatus').textContent = 'Flashing firmware... ESP32 akan restart';
        document.getElementById('otaStatus').style.color = 'var(--orange)';
      }
    }
  };

  function showSuccess() {
    document.getElementById('otaProgressBar').style.width = '100%';
    document.getElementById('otaProgressBar').style.background = 'var(--green)';
    document.getElementById('otaStatus').textContent = 'Update berhasil! ESP32 restart...';
    document.getElementById('otaStatus').style.color = 'var(--green)';
    btn.textContent = '✓ Berhasil!';
    setTimeout(function() {
      document.body.innerHTML = "<div style='text-align:center;margin-top:80px;font-family:monospace;'><div style='color:#00e676;font-size:2em;'>&#10003; UPDATE BERHASIL</div><div style='color:#6a6a88;margin-top:20px;font-size:0.9em;line-height:2;'>ESP32 sedang restart...<br>Tunggu 5 detik lalu reconnect WiFi<br><strong style=\"color:#aaa;\">CBR250RR-RPM-Monitor</strong></div></div>";
    }, 2000);
  }

  xhr.onload = function() {
    if (xhr.status === 200) {
      showSuccess();
    } else {
      // Kalau upload sudah 100% tapi response non-200, kemungkinan ESP32 sudah restart
      if (uploadComplete) {
        showSuccess();
      } else {
        document.getElementById('otaStatus').textContent = 'Gagal: ' + (xhr.responseText || 'Unknown error');
        document.getElementById('otaStatus').style.color = 'var(--red)';
        btn.disabled = false;
        btn.textContent = '&#8593; Upload Firmware';
      }
    }
  };

  xhr.onerror = function() {
    // ESP32 restart setelah flashing → koneksi putus → onerror dipanggil
    // Jika upload sudah 100%, ini BUKAN error — OTA berhasil
    if (uploadComplete) {
      showSuccess();
    } else {
      document.getElementById('otaStatus').textContent = 'Error koneksi saat upload. Coba lagi.';
      document.getElementById('otaStatus').style.color = 'var(--red)';
      btn.disabled = false;
      btn.textContent = '&#8593; Upload Firmware';
    }
  };

  xhr.ontimeout = function() {
    if (uploadComplete) {
      showSuccess();
    } else {
      document.getElementById('otaStatus').textContent = 'Timeout. Coba lagi.';
      document.getElementById('otaStatus').style.color = 'var(--red)';
      btn.disabled = false;
      btn.textContent = '&#8593; Upload Firmware';
    }
  };

  const formData = new FormData();
  formData.append('firmware', file, file.name);
  xhr.send(formData);
}
</script>
