<script>
let activeInputs = new Set();

function addHotspotTime() {
  fetch('/add-hotspot-time').then(r => r.json()).then(() => { updateRPM(); });
}

function turnOffHotspotNow() {
  if (confirm("Matikan Hotspot dan Web Server sekarang?")) {
    fetch('/force-hotspot-off').then(() => {
      document.body.innerHTML = "<h1 style='text-align:center;margin-top:50px;color:#e8000d;font-family:monospace;'>SYSTEM OFF</h1><p style='color:#6a6a88;text-align:center;margin-top:12px;font-family:monospace;'>Connection closed.</p>";
    }).catch(() => {
      document.body.innerHTML = "<h1 style='text-align:center;margin-top:50px;color:#e8000d;font-family:monospace;'>SYSTEM OFF</h1>";
    });
  }
}

function openModal(id)  { document.getElementById(id).style.display = 'block'; if (id === 'pulserModal') scopeStart(); }
function closeModal(id) {
  document.getElementById(id).style.display = 'none';
  if (id === 'pulserModal') scopeStop();
  const modal = document.getElementById(id);
  modal.querySelectorAll('.setting-input').forEach(i => activeInputs.delete(i.id));
}

window.onclick = function(e) {
  if (e.target.classList.contains('modal')) { e.target.style.display = 'none'; if (e.target.id === 'pulserModal') scopeStop(); }
};

function updatePitCalc(ratio, period) {
  const offMs  = Math.round((ratio / 100) * period);
  const onMs   = Math.max(period - offMs, 3);
  document.getElementById('pitOffMsDisplay').textContent = offMs;
  document.getElementById('pitOnMsDisplay').textContent  = onMs;
}

document.addEventListener('DOMContentLoaded', function() {
  document.querySelectorAll('.setting-input').forEach(input => {
    input.addEventListener('focus', function() { activeInputs.add(this.id); });
    input.addEventListener('input', function() {
      activeInputs.add(this.id);
      if (this.id === 'pitCutRatioInput' || this.id === 'pitPwmPeriodInput') {
        const ratio  = parseFloat(document.getElementById('pitCutRatioInput').value)  || 75;
        const period = parseInt(document.getElementById('pitPwmPeriodInput').value) || 38;
        updatePitCalc(ratio, period);
      }
    });
    input.addEventListener('keydown', function(e) { if (e.key === 'Enter') this.blur(); });
  });
});

function updateRPM() {
  fetch('/rpm-data?t=' + Date.now())
    .then(r => r.json())
    .then(data => {
      document.getElementById('rpmValue').textContent        = Math.round(data.rpm);
      document.getElementById('controlRpmValue').textContent = Math.round(data.controlRpm);
      document.getElementById('maxRpm').textContent          = Math.round(data.maxRpm);
      document.getElementById('systemStatus').textContent    = data.systemStatus;
      document.getElementById('clutchStatus').textContent    = data.clutchEngaged ? "ENGAGED" : "FREE";
      document.getElementById('ignitionStatus').textContent  = data.ignitionCut ? "CUT" : "ON";

      // status dots
      document.getElementById('sysDot').style.background =
        data.systemStatus !== 'NORMAL' ? 'var(--red)' : 'var(--green)';
      document.getElementById('clutchDot').style.background =
        data.clutchEngaged ? 'var(--orange)' : 'var(--muted)';
      document.getElementById('ignDot').style.background =
        data.ignitionCut ? 'var(--red)' : 'var(--green)';

      const el = document.getElementById('hotspotTimeout');
      if (data.hotspotActive && data.hotspotAutoOffEnabled) {
        const rem = Math.max(0, data.hotspotRemainingTime);
        const m   = Math.floor(rem / 60000);
        const s   = Math.floor((rem % 60000) / 1000);
        el.textContent = m + ':' + String(s).padStart(2, '0');
        el.style.color = rem < 10000 ? 'var(--red)' : 'var(--orange)';
      } else {
        el.textContent = "DISABLED";
        el.style.color = 'var(--muted)';
      }

      updateSystemStatus(data);
      if (activeInputs.size === 0) updateInputValues(data);
    })
    .catch(err => console.error('Error:', err));
}

function updateSystemStatus(data) {
  updateBadge('launchStatus',      data.launchControlEnabled, data.launchControlActive);
  updateBadge('pitStatus',         data.pitLimiterEnabled,    data.pitLimiterActive);
  updateBadge('backfireStatus',    data.backfireEnabled,      data.backfireActive);
  updateBadge('quickshifterStatus',data.quickShifterEnabled,  data.quickshifterActive);
  updateBadge('warmupStatus',      data.autoWarmUpEnabled,    data.warmUpActive);
  updateBadge('timingkudaStatus',  data.timingKudaEnabled,    data.timingKudaActive);

  updateButton('launchBtn',      data.launchControlEnabled);
  updateButton('pitBtn',         data.pitLimiterEnabled);
  updateButton('backfireBtn',    data.backfireEnabled);
  updateButton('quickshifterBtn',data.quickShifterEnabled);
  updateButton('warmupBtn',      data.autoWarmUpEnabled);
  updateButton('timingkudaBtn',  data.timingKudaEnabled);

  // card active state
  setCardActive('launchStatus',      data.launchControlEnabled || data.launchControlActive);
  setCardActive('pitStatus',         data.pitLimiterEnabled    || data.pitLimiterActive);
  setCardActive('backfireStatus',    data.backfireEnabled      || data.backfireActive);
  setCardActive('quickshifterStatus',data.quickShifterEnabled  || data.quickshifterActive);
  setCardActive('warmupStatus',      data.autoWarmUpEnabled    || data.warmUpActive);
  setCardActive('timingkudaStatus',  data.timingKudaEnabled    || data.timingKudaActive);
}

function setCardActive(badgeId, isActive) {
  const badge = document.getElementById(badgeId);
  if (badge) {
    const card = badge.closest('.system-card');
    if (card) card.classList.toggle('active', isActive);
  }
}

function updateBadge(id, enabled, active) {
  const el = document.getElementById(id);
  if (active)        { el.textContent = 'ACTIVE'; el.className = 'system-status active'; }
  else if (enabled)  { el.textContent = 'ON';     el.className = 'system-status on'; }
  else               { el.textContent = 'OFF';    el.className = 'system-status'; }
}

function updateButton(id, enabled) {
  const btn = document.getElementById(id);
  btn.textContent = enabled ? 'Disable' : 'Enable';
  btn.className   = enabled ? 'btn btn-on' : 'btn btn-off';
}

function updateInputValues(data) {
  document.getElementById('launchRpmInput').value                     = data.launchControlLimit   || 8000;
  document.getElementById('launchDelayInput').value                   = (data.launchControlDelay / 1000) || 3;
  document.getElementById('softCutRangeInput').value                  = data.softCutRange          || 300;
  document.getElementById('pitRpmInput').value                        = data.pitLimiterLimit      || 6000;
  document.getElementById('pitCutRatioInput').value                   = data.pitCutRatio           || 75;
  document.getElementById('pitPwmPeriodInput').value                  = data.pitPwmPeriod          || 38;
  updatePitCalc(data.pitCutRatio || 75, data.pitPwmPeriod || 38);
  document.getElementById('backfireRpmInput').value                   = data.backfireRPMLimit     || 4000;
  document.getElementById('quickshifterMinRpmInput').value            = data.quickshifterMinRPM   || 0;
  document.getElementById('quickshifterCooldownInput').value          = data.quickshifterCooldownTime || 150;
  document.getElementById('quickshifterCut3000Input').value           = data.quickshifterCutTime3000  || 50;
  document.getElementById('quickshifterCut6000Input').value           = data.quickshifterCutTime6000  || 40;
  document.getElementById('quickshifterCut9000Input').value           = data.quickshifterCutTime9000  || 30;
  document.getElementById('quickshifterCut12000Input').value          = data.quickshifterCutTime12000 || 20;
  document.getElementById('quickshifterDownshiftDurationInput').value = data.quickshifterDownshiftDuration || 100;
  document.getElementById('quickshifterUpCheckbox').checked           = data.quickshifterUpEnabled   !== false;
  document.getElementById('quickshifterDownCheckbox').checked         = data.quickshifterDownEnabled !== false;
  document.getElementById('warmupRpmInput').value                     = data.warmUpRPMLimit   || 3000;
  document.getElementById('warmupDurationInput').value                = (data.warmUpDuration / 60000) || 3;
  document.getElementById('warmupRiseTimeInput').value                = data.warmUpRiseTime   || 70;
  document.getElementById('warmupIdleTimeInput').value                = data.warmUpIdleTime   || 1000;
  document.getElementById('timingkudaRpmInput').value                 = data.timingKudaRPMLimit     || 1800;
  document.getElementById('timingkudaCutInput').value                 = data.timingKudaCutDuration   || 100;
  document.getElementById('timingkudaIntervalInput').value            = data.timingKudaCutInterval   || 500;
}

function toggleLaunchControl()  { fetch('/toggle-launch').then(updateRPM); }
function togglePitLimiter()     { fetch('/toggle-pit').then(updateRPM); }
function toggleBackfire()       { fetch('/toggle-backfire').then(updateRPM); }
function toggleQuickShifter()   { fetch('/toggle-quickshifter').then(updateRPM); }
function toggleAutoWarmUp()     { fetch('/toggle-warmup').then(updateRPM); }
function toggleTimingKuda()     { fetch('/toggle-timingkuda').then(updateRPM); }
function resetMaxRPM()          { fetch('/reset-max').then(updateRPM); }
function disableAll()           { fetch('/disable-all').then(updateRPM); }

function saveAllSettings() {
  if (confirm('Save all settings to EEPROM?')) {
    fetch('/save-settings').then(r => r.json()).then(data => {
      alert(data.status === 'success' ? 'Saved!' : 'Error saving!');
    });
  }
}

function saveLaunchSettings() {
  const rpm     = parseFloat(document.getElementById('launchRpmInput').value);
  const delay   = parseFloat(document.getElementById('launchDelayInput').value);
  const softCut = parseFloat(document.getElementById('softCutRangeInput').value);
  if (rpm < 4000 || rpm > 12000)      { alert('RPM harus antara 4000-12000'); return; }
  if (delay < 1  || delay > 10)       { alert('Delay harus antara 1-10 detik'); return; }
  if (softCut < 100 || softCut > 500) { alert('Soft Cut Zone harus antara 100-500 RPM'); return; }
  fetch('/set-launch-rpm?value=' + rpm)
    .then(() => fetch('/set-launch-delay?value=' + Math.round(delay * 1000)))
    .then(() => fetch('/set-softcut-range?value=' + softCut))
    .then(() => { closeModal('launchModal'); updateRPM(); });
}

function savePitSettings() {
  const rpm       = parseInt(document.getElementById('pitRpmInput').value);
  const cutRatio  = parseFloat(document.getElementById('pitCutRatioInput').value);
  const pwmPeriod = parseInt(document.getElementById('pitPwmPeriodInput').value);
  if (rpm < 3000 || rpm > 8000)         { alert('RPM harus antara 3000-8000'); return; }
  if (cutRatio < 50 || cutRatio > 90)   { alert('Cut Ratio harus antara 50-90%'); return; }
  if (pwmPeriod < 20 || pwmPeriod > 60) { alert('PWM Period harus antara 20-60ms'); return; }
  Promise.all([
    fetch('/set-pit-rpm?value='        + rpm),
    fetch('/set-pit-cut-ratio?value='  + cutRatio),
    fetch('/set-pit-pwm-period?value=' + pwmPeriod)
  ]).then(() => { closeModal('pitModal'); updateRPM(); });
}

function saveBackfireSettings() {
  const rpm = parseInt(document.getElementById('backfireRpmInput').value);
  if (rpm < 2000 || rpm > 8000) { alert('RPM harus antara 2000-8000'); return; }
  fetch('/set-backfire-rpm?value=' + rpm).then(() => { closeModal('backfireModal'); updateRPM(); });
}

function saveQuickShifterSettings() {
  const minRpm   = parseInt(document.getElementById('quickshifterMinRpmInput').value)             || 0;
  const cooldown = parseInt(document.getElementById('quickshifterCooldownInput').value)           || 150;
  const cut3000  = parseInt(document.getElementById('quickshifterCut3000Input').value)            || 60;
  const cut6000  = parseInt(document.getElementById('quickshifterCut6000Input').value)            || 50;
  const cut9000  = parseInt(document.getElementById('quickshifterCut9000Input').value)            || 40;
  const cut12000 = parseInt(document.getElementById('quickshifterCut12000Input').value)           || 30;
  const downDur  = parseInt(document.getElementById('quickshifterDownshiftDurationInput').value)  || 100;
  const upEn     = document.getElementById('quickshifterUpCheckbox').checked;
  const downEn   = document.getElementById('quickshifterDownCheckbox').checked;
  Promise.all([
    fetch('/set-quickshifter-minrpm?value='             + minRpm),
    fetch('/set-quickshifter-cooldown?value='           + cooldown),
    fetch('/set-quickshifter-cut-3000?value='           + cut3000),
    fetch('/set-quickshifter-cut-6000?value='           + cut6000),
    fetch('/set-quickshifter-cut-9000?value='           + cut9000),
    fetch('/set-quickshifter-cut-12000?value='          + cut12000),
    fetch('/set-quickshifter-downshift-duration?value=' + downDur),
    fetch('/set-quickshifter-up?value='   + (upEn   ? '1' : '0')),
    fetch('/set-quickshifter-down?value=' + (downEn ? '1' : '0'))
  ]).then(() => { closeModal('quickshifterModal'); updateRPM(); });
}

function testQSUp() {
  fetch('/test-qs-up')
    .then(r => r.json())
    .then(d => {
      if (d.status === 'success') alert('QS Up triggered! Ignition cut aktif selama ' + d.cutMs + ' ms.');
      else alert('Gagal: ' + d.message);
    });
}

function testQSDown() {
  fetch('/test-qs-down')
    .then(r => r.json())
    .then(d => {
      if (d.status === 'success') alert('QS Down triggered! Throttle blip aktif selama ' + d.durationMs + ' ms.');
      else alert('Gagal: ' + d.message);
    });
}

function saveWarmUpSettings() {
  const rpm      = parseInt(document.getElementById('warmupRpmInput').value)      || 3000;
  const duration = parseInt(document.getElementById('warmupDurationInput').value) || 3;
  const riseTime = parseInt(document.getElementById('warmupRiseTimeInput').value) || 70;
  const idleTime = parseInt(document.getElementById('warmupIdleTimeInput').value) || 1000;
  Promise.all([
    fetch('/set-warmup-rpm?value='      + rpm),
    fetch('/set-warmup-duration?value=' + (duration * 60000)),
    fetch('/set-warmup-risetime?value=' + riseTime),
    fetch('/set-warmup-idletime?value=' + idleTime)
  ]).then(() => { closeModal('warmupModal'); updateRPM(); });
}

function saveTimingKudaSettings() {
  const rpm      = parseInt(document.getElementById('timingkudaRpmInput').value);
  const cut      = parseInt(document.getElementById('timingkudaCutInput').value);
  const interval = parseInt(document.getElementById('timingkudaIntervalInput').value);
  Promise.all([
    fetch('/set-timingkuda-rpm?value='      + rpm),
    fetch('/set-timingkuda-cut?value='      + cut),
    fetch('/set-timingkuda-interval?value=' + interval)
  ]).then(() => { closeModal('timingkudaModal'); updateRPM(); });
}

setInterval(updateRPM, 100);
updateRPM();
</script>

<script>
// ══ PULSER SCOPE ══
const SC = { run:false, timer:null, raf:0, since:null, edges:[], tdiv:10,
             frozen:false, frozenT:0, ppr:13.3, info:0,
             demo:false, demoT:0, demoPhase:0, lastStat:0 };

function scopeStart() {
  if (SC.run) return;
  SC.run = true; SC.since = null; SC.edges = [];
  scopePoll();
  SC.raf = requestAnimationFrame(scopeDraw);
}
function scopeStop() {
  SC.run = false;
  clearTimeout(SC.timer);
  cancelAnimationFrame(SC.raf);
}
function scopeSetTdiv(v) { SC.tdiv = parseFloat(v) || 10; }
function scopeToggleFreeze() {
  SC.frozen = !SC.frozen;
  if (SC.frozen) SC.frozenT = performance.now() - 130;
  document.getElementById('scopeFreezeBtn').innerHTML = SC.frozen ? '&#9654; Run' : '&#10073;&#10073; Freeze';
  if (!SC.frozen && !SC.demo) { SC.since = null; scopePoll(); }
}
function scopeToggleDemo() {
  SC.demo = !SC.demo;
  SC.edges = []; SC.since = null;
  SC.demoT = performance.now(); SC.demoPhase = 0;
  document.getElementById('scopeDemoBtn').innerHTML = SC.demo ? '&#9632; Stop Simulasi' : '&#9654; Simulasi';
  if (!SC.demo) scopePoll();
}

function scopePoll() {
  if (!SC.run || SC.demo || SC.frozen) return;
  clearTimeout(SC.timer);
  const q = (SC.since === null) ? '' : ('?since=' + SC.since);
  fetch('/pulser-data' + q, { cache: 'no-store' })
    .then(r => r.text())
    .then(txt => {
      if (!SC.run || SC.demo || SC.frozen) return;
      const tRecv = performance.now();
      const a = txt.trim().split(/\s+/).map(Number);
      if (a.length < 5) return;
      const now = a[0] | 0, head = a[1], cnt = a[2];
      SC.info = a[3]; SC.ppr = a[4] / 100 || 13.3;
      SC.since = head;
      for (let i = 0; i < cnt; i++) {
        const v = a[5 + i];
        if (isNaN(v)) continue;
        const age = ((now - (v & ~1)) >>> 0) / 1000;   // ms
        SC.edges.push({ t: tRecv - age, ign: v & 1 });
      }
      // buang data lama (>2 detik)
      const cut = tRecv - 2000;
      let k = 0; while (k < SC.edges.length && SC.edges[k].t < cut) k++;
      if (k > 0) SC.edges.splice(0, k);
    })
    .catch(() => {})
    .finally(() => { if (SC.run && !SC.demo && !SC.frozen) SC.timer = setTimeout(scopePoll, 100); });
}

function scopeGenDemo(tNow) {
  // simulasi 6000 RPM, pit limiter hard cut: period 38 pulse, ratio 75%
  const rpm = 6000, ppr = SC.ppr || 13.3;
  const iv = 60000 / (rpm * ppr);               // ms per pulse
  const period = 38, off = Math.round(0.75 * period);
  SC.info = 1 | (period << 8) | (off << 16);
  while (SC.demoT <= tNow) {
    SC.edges.push({ t: SC.demoT, ign: (SC.demoPhase < period - off) ? 1 : 0 });
    SC.demoPhase = (SC.demoPhase + 1) % period;
    SC.demoT += iv * (1 + (Math.random() - 0.5) * 0.04);
  }
  const cut = tNow - 2000;
  let k = 0; while (k < SC.edges.length && SC.edges[k].t < cut) k++;
  if (k > 0) SC.edges.splice(0, k);
}

function scopeLowerBound(e, t) {
  let lo = 0, hi = e.length;
  while (lo < hi) { const m = (lo + hi) >> 1; if (e[m].t < t) lo = m + 1; else hi = m; }
  return lo;
}

function scopeStats(tR) {
  const e = SC.edges;
  const set = (id, v) => { document.getElementById(id).textContent = v; };
  const i0 = scopeLowerBound(e, tR - 400);
  let n = 0, sum = 0, sq = 0, prev = null;
  for (let i = i0; i < e.length && e[i].t <= tR; i++) {
    if (prev !== null) { const d = (e[i].t - prev) * 1000; n++; sum += d; sq += d * d; }
    prev = e[i].t;
  }
  if (n < 3 || tR - prev > 300) {
    set('scFreq','-'); set('scRpm','-'); set('scPeriod','-'); set('scJitter','-');
  } else {
    const mean = sum / n, sd = Math.sqrt(Math.max(sq / n - mean * mean, 0));
    const f = 1e6 / mean;
    set('scFreq', f.toFixed(0) + ' Hz');
    set('scRpm', Math.round(f * 60 / SC.ppr));
    set('scPeriod', mean.toFixed(0) + ' us');
    set('scJitter', (sd / mean * 100).toFixed(1) + '%');
  }
  // % pulse yang ter-CUT (60 pulse terakhir)
  const iEnd = scopeLowerBound(e, tR + 0.001);
  const iS = Math.max(0, iEnd - 60);
  let c = 0, m = 0;
  for (let i = iS; i < iEnd; i++) { m++; if (!e[i].ign) c++; }
  set('scCut', m ? Math.round(c / m * 100) + '%' : '-');
  const act = SC.info & 1, per = (SC.info >> 8) & 255, off = (SC.info >> 16) & 255;
  set('scMode', act ? ('PULSE-CUT ' + off + '/' + per) : 'PASSIVE');
}

function scopeDraw() {
  if (!SC.run) return;
  SC.raf = requestAnimationFrame(scopeDraw);

  const cv = document.getElementById('scopeCanvas');
  const dpr = window.devicePixelRatio || 1;
  const cw = cv.clientWidth, ch = cv.clientHeight;
  if (!cw || !ch) return;
  if (cv.width !== Math.round(cw * dpr) || cv.height !== Math.round(ch * dpr)) {
    cv.width = Math.round(cw * dpr); cv.height = Math.round(ch * dpr);
  }
  const g = cv.getContext('2d');
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  g.fillStyle = '#030d08'; g.fillRect(0, 0, cw, ch);

  // grid
  const DX = 10, DY = 8;
  g.lineWidth = 1; g.strokeStyle = '#0d3a22'; g.beginPath();
  for (let i = 0; i <= DX; i++) { const x = Math.round(i * cw / DX) + 0.5; g.moveTo(x, 0); g.lineTo(x, ch); }
  for (let j = 0; j <= DY; j++) { const y = Math.round(j * ch / DY) + 0.5; g.moveTo(0, y); g.lineTo(cw, y); }
  g.stroke();

  const nowT = performance.now();
  if (SC.demo) scopeGenDemo(nowT);
  const win = SC.tdiv * DX;
  const tR = SC.frozen ? SC.frozenT : (nowT - 130);
  const tL = tR - win;
  const px = t => (t - tL) / win * cw;
  const e = SC.edges;

  const y1b = ch * 0.40, y1h = ch * 0.07;
  const y2h = ch * 0.60, y2l = ch * 0.92;

  let i0 = scopeLowerBound(e, tL) - 1; if (i0 < 0) i0 = 0;
  let iEnd = scopeLowerBound(e, tR + 0.001);
  const hasSig = iEnd > 0 && (tR - e[iEnd - 1].t) < 300;

  // CH1 — pulser
  g.strokeStyle = '#ffd600'; g.lineWidth = 1.5;
  g.shadowColor = '#ffd600'; g.shadowBlur = 4;
  g.beginPath(); g.moveTo(-5, y1b);
  for (let i = i0; i < iEnd; i++) {
    const t = e[i].t;
    const iv = (i + 1 < e.length) ? (e[i + 1].t - t) : (i > 0 ? t - e[i - 1].t : 1);
    const w = Math.min(Math.max(iv * 0.3, 0.01), 0.25);
    const x = px(t), x2 = Math.max(px(t + w), x + 1.5);
    g.lineTo(x, y1b); g.lineTo(x, y1h); g.lineTo(x2, y1h); g.lineTo(x2, y1b);
  }
  g.lineTo(cw + 5, y1b); g.stroke();

  // CH2 — ignition (hijau = ON, merah = CUT)
  const pg = new Path2D(), pr = new Path2D();
  let lastY = null;
  for (let i = i0; i < iEnd; i++) {
    const lvl = e[i].ign, y = lvl ? y2h : y2l, P = lvl ? pg : pr;
    const xs = Math.max(px(e[i].t), -5);
    const xe = (i + 1 < iEnd) ? px(e[i + 1].t) : px(tR);
    if (lastY !== null) { P.moveTo(xs, lastY); P.lineTo(xs, y); } else { P.moveTo(xs, y); }
    P.lineTo(xe, y);
    lastY = y;
  }
  g.lineWidth = 1.5;
  g.shadowColor = '#00e676'; g.strokeStyle = '#00e676'; g.stroke(pg);
  g.shadowColor = '#ff1744'; g.strokeStyle = '#ff1744'; g.stroke(pr);
  g.shadowBlur = 0;

  // label
  g.font = '10px "Courier New", monospace';
  g.fillStyle = '#ffd600'; g.fillText('CH1 PULSER', 6, 12);
  g.fillStyle = '#00e676'; g.fillText('CH2 IGN', 6, ch * 0.54);
  g.fillStyle = '#4a8f6a'; g.textAlign = 'right';
  g.fillText(SC.tdiv + ' ms/div' + (SC.frozen ? '  [FREEZE]' : '') + (SC.demo ? '  [SIMULASI]' : ''), cw - 6, 12);
  g.textAlign = 'left';
  if (!hasSig) {
    g.fillStyle = '#ff6600'; g.font = 'bold 14px "Courier New", monospace'; g.textAlign = 'center';
    g.fillText('NO SIGNAL', cw / 2, ch / 2); g.textAlign = 'left';
  }

  if (nowT - SC.lastStat > 250) { SC.lastStat = nowT; scopeStats(tR); }
}
</script>
</body>
</html>
)rawliteral";

// ============================================
// EEPROM FUNCTIONS
// ============================================
void saveConfig() {
  EEPROM.begin(EEPROM_SIZE);
  EEPROM.put(EEPROM_START_ADDR, config);
  EEPROM.commit();
  EEPROM.end();
  Serial.println("Config saved to EEPROM");
}

void loadConfig() {
  EEPROM.begin(EEPROM_SIZE);
  EEPROM.get(EEPROM_START_ADDR, config);
  EEPROM.end();

  if (strcmp(config.version, CONFIG_VERSION) != 0) {
