// ============================================
// INTERRUPT SERVICE ROUTINES
// ============================================
// (pulseInterrupt dipindah ke bawah #define IGN_CUT/IGN_NORMAL — v29)

// ============================================
// IGNITION RELAY POLARITY
// Sesuaikan dengan tipe relay yang dipakai:
//   ACTIVE_HIGH = relay aktif (cut) saat pin HIGH, idle saat pin LOW
//   ACTIVE_LOW  = relay aktif (cut) saat pin LOW,  idle saat pin HIGH  ← default kebanyakan relay modul
//
// Cara test: ukur GPIO 19 saat idle (motor tidak jalan, QS tidak aktif)
//   Kalau 3.3V (HIGH) dan relay ON  → ganti ke ACTIVE_HIGH
//   Kalau 0V   (LOW)  dan relay OFF → biarkan ACTIVE_LOW
// ============================================
// ============================================
// IGNITION RELAY POLARITY
// Sesuaikan dengan tipe relay yang dipakai:
//   IGN_CUT    = level untuk AKTIFKAN cut (ignition OFF)
//   IGN_NORMAL = level untuk IDLE (ignition ON)
//
// Default: relay active LOW (kebanyakan relay modul)
//   IGN_CUT = LOW  → relay ON → ignition mati
//   IGN_NORMAL = HIGH → relay OFF → ignition hidup
//
// Jika relay active HIGH, tukar nilainya.
// ============================================
#define IGN_CUT    LOW
#define IGN_NORMAL HIGH

// ============================================
// v29: PULSE-BASED CUT (Pit Limiter + Launch Control soft cut)
// Cut sekarang di-eksekusi LANGSUNG di ISR pulser, bukan timer millis().
//   Siklus = isrPeriod pulse. Dalam 1 siklus:
//     pulse 0 .. onCount-1        -> ignition ON
//     pulse onCount .. period-1   -> ignition CUT
//   Cut selalu sinkron dengan putaran mesin (tidak drift terhadap RPM)
//   dan tidak terpengaruh jitter loop 1 ms.
// ============================================
volatile bool     isrCutMode  = false;   // true = ISR yang pegang pin ignition
volatile uint32_t isrPeriod   = 24;      // panjang siklus (pulse)
volatile uint32_t isrOffCount = 12;      // jumlah pulse CUT dalam 1 siklus
volatile uint32_t isrPhase    = 0;       // posisi pulse dalam siklus

static inline void IRAM_ATTR ignWriteFast(bool cut) {
  bool level = cut ? (IGN_CUT) : (IGN_NORMAL);
  if (level) GPIO.out_w1ts = (1UL << ignitionPin);
  else       GPIO.out_w1tc = (1UL << ignitionPin);
}

// v29: ring buffer untuk Pulser Scope (modal oscilloscope di web UI)
// Tiap pulse (RISING) dicatat: timestamp us (bit 0 diganti status ignition setelah pulse itu)
//   bit0 = 1 -> ignition ON, bit0 = 0 -> ignition CUT
#define SCOPE_BUF       512          // harus pangkat 2
#define SCOPE_SEND_MAX  448
volatile uint32_t scopeBuf[SCOPE_BUF];
volatile uint32_t scopeHead = 0;

void IRAM_ATTR pulseInterrupt() {
  pulseCount++;
  if (isrCutMode) {
    uint32_t p       = isrPhase;
    uint32_t period  = isrPeriod;
    uint32_t onCount = period - isrOffCount;
    ignWriteFast(p >= onCount);
    if (++p >= period) p = 0;
    isrPhase = p;
  }
  // --- catat ke scope buffer ---
  uint32_t ts  = (uint32_t)esp_timer_get_time();
  uint32_t ign = (((GPIO.out >> ignitionPin) & 1UL) == (uint32_t)(IGN_NORMAL)) ? 1UL : 0UL;
  uint32_t h   = scopeHead;
  scopeBuf[h & (SCOPE_BUF - 1)] = (ts & 0xFFFFFFFEUL) | ign;
  scopeHead = h + 1;
}

// Dipanggil dari Core 1 (controlIgnition)
static void pulseCutStart(uint32_t period, uint32_t offCount) {
  if (period < 4) period = 4;
  if (offCount < 1) offCount = 1;
  if (offCount > period - 1) offCount = period - 1;
  isrPeriod   = period;
  isrOffCount = offCount;
  if (!isrCutMode) {
    isrPhase   = 0;
    isrCutMode = true;
  }
}

static void pulseCutStop() {
  isrCutMode = false;   // ISR berhenti nulis pin; setelah ini baru boleh digitalWrite
}

// ============================================
// DAC RAMP untuk QS Downshift blip
// ============================================
static void qsDacRamp(uint16_t fromAP1, uint16_t toAP1,
                      uint16_t fromAP2, uint16_t toAP2,
                      unsigned long totalMs, uint8_t steps = 8) {
  if (steps < 1) steps = 1;
  unsigned long dt = totalMs / steps;
  for (uint8_t i = 1; i <= steps; i++) {
    uint16_t v1 = fromAP1 + (int32_t)(toAP1 - fromAP1) * i / steps;
    uint16_t v2 = fromAP2 + (int32_t)(toAP2 - fromAP2) * i / steps;
    dac1.setVoltage(v1, false);
    dac2.setVoltage(v2, false);
    vTaskDelay(max(1UL, dt) / portTICK_PERIOD_MS);
  }
}

// ============================================
// QUICK SHIFTER HANDLER — v28 (tulis ulang bersih)
//
// Sensor: NJK-5002C NPN Normally Open + INPUT_PULLUP
//   Idle  = pin HIGH  (pullup aktif, sensor output floating)
//   Aktif = pin LOW   (sensor tarik output ke GND)
//
// Logika IDLE:
//   Baca pin langsung setiap loop — TIDAK ada deteksi edge, TIDAK ada prev state.
//   Kalau pin LOW → trigger INSTAN → masuk QS_CUTTING.
//   Kenapa tidak pakai edge detection?
//   Karena edge detection membutuhkan 2 loop (prev HIGH lalu cur LOW).
//   Selama QS_CUTTING dan QS_COOLDOWN, sensor TIDAK dibaca → tidak bisa
//   false trigger ulang meski pin tetap LOW.
//
// CUTTING (Upshift):
//   - Ignition LOW selama cutTime ms (ditentukan dari RPM saat trigger)
//   - Selesai → ignition HIGH → QS_COOLDOWN
//
// CUTTING (Downshift):
//   - DAC ramp naik → hold → turun (throttle blip)
//   - Selesai → QS_COOLDOWN
//
// COOLDOWN:
//   - Sensor tidak dibaca selama quickShifterCooldownTime ms
//   - Anti double trigger
//   - Selesai → QS_IDLE
// ============================================
void handleQuickShifter() {
  if (!quickShifterEnabled) {
    // Pastikan ignition normal jika QS dimatikan saat cutting
    if (qsState == QS_CUTTING) {
      digitalWrite(ignitionPin, IGN_NORMAL);
      dac1.setVoltage(DAC_IDLE_AP1, false);
      dac2.setVoltage(DAC_IDLE_AP2, false);
    }
    qsState = QS_IDLE;
    return;
  }

  // ── QS_IDLE ────────────────────────────────────────────────────
  if (qsState == QS_IDLE) {
    bool rpmOk = (quickShifterMinRPM == 0 || controlRPM >= (float)quickShifterMinRPM);

    // Baca pin langsung — LOW = sensor aktif = trigger instan
    if (quickShifterUpEnabled && rpmOk && digitalRead(quickShifterUpPin) == LOW) {
      qsIsUpshift   = true;
      qsCutStartMs  = millis();
      qsDacWritten  = false;
      pulseCutStop();   // v29: ISR lepas pin sebelum QS ambil alih
      qsState       = QS_CUTTING;
      Serial.printf("[QS] UP triggered. RPM=%.0f\n", controlRPM);
      return;
    }

    if (quickShifterDownEnabled && rpmOk && digitalRead(quickShifterDownPin) == LOW) {
      qsIsUpshift   = false;
      qsCutStartMs  = millis();
      qsDacWritten  = false;
      pulseCutStop();   // v29: ISR lepas pin sebelum QS ambil alih
      qsState       = QS_CUTTING;
      Serial.printf("[QS] DOWN triggered. RPM=%.0f\n", controlRPM);
      return;
    }
    return;
  }

  // ── QS_CUTTING ──────────────────────────────────────────────────
  if (qsState == QS_CUTTING) {
    unsigned long elapsedMs = millis() - qsCutStartMs;

    if (qsIsUpshift) {
      // Tentukan cut time dari RPM saat trigger
      unsigned long cutTime = quickShifterCutTime3000;
      if      (controlRPM >= 12000) cutTime = quickShifterCutTime12000;
      else if (controlRPM >= 9000)  cutTime = quickShifterCutTime9000;
      else if (controlRPM >= 6000)  cutTime = quickShifterCutTime6000;

      if (elapsedMs < cutTime) {
        digitalWrite(ignitionPin, IGN_CUT);
      } else {
        digitalWrite(ignitionPin, IGN_NORMAL);
        qsCooldownStart = millis();
        qsState         = QS_COOLDOWN;
        Serial.printf("[QS] UP selesai. cut=%lums\n", cutTime);
      }

    } else {
      // Downshift — jalankan throttle blip SEKALI
      if (!qsDacWritten) {
        qsDacWritten = true;
        unsigned long dur   = quickShifterDownshiftDuration;
        unsigned long rampMs = dur / 3;
        if (rampMs < 10) rampMs = 10;
        unsigned long holdMs = dur - (rampMs * 2);
        if (holdMs < 1) holdMs = 1;

        qsDacRamp(DAC_IDLE_AP1, DAC_WARM_UP_AP1, DAC_IDLE_AP2, DAC_WARM_UP_AP2, rampMs);
        vTaskDelay(holdMs / portTICK_PERIOD_MS);
        bool warmNow = autoWarmUpEnabled && warmUpActive;
        uint16_t endAP1 = warmNow ? DAC_WARM_UP_AP1 : DAC_IDLE_AP1;
        uint16_t endAP2 = warmNow ? DAC_WARM_UP_AP2 : DAC_IDLE_AP2;
        qsDacRamp(DAC_WARM_UP_AP1, endAP1, DAC_WARM_UP_AP2, endAP2, rampMs);

        qsCooldownStart = millis();
        qsState         = QS_COOLDOWN;
        Serial.printf("[QS] DOWN selesai. dur=%lums\n", dur);
      }
    }
    return;
  }

  // ── QS_COOLDOWN ─────────────────────────────────────────────────
  if (qsState == QS_COOLDOWN) {
    if (millis() - qsCooldownStart >= quickShifterCooldownTime) {
      qsState = QS_IDLE;
      Serial.println("[QS] Cooldown selesai, siap trigger.");
    }
  }
}

// ============================================
void calculateRPM() {
  unsigned long currentTime = millis();
  if (currentTime - lastCalculationTime < CALCULATION_INTERVAL) return;

  noInterrupts();
  unsigned long curPulse = pulseCount;
  interrupts();

  unsigned long elapsed = currentTime - lastCalculationTime;
  unsigned long pulses  = curPulse - lastPulseCount;

  if (pulses > 0 && elapsed > 0) {
    float frequency = (pulses * 1000.0f) / (float)elapsed;
    float rawRPM    = (frequency * 60.0f) / PULSES_PER_REVOLUTION;

    bool isSpike = false;
    if (lastValidRPM > 0) {
      float rise = rawRPM - lastValidRPM;
      float drop = lastValidRPM - rawRPM;
      if (rise > SPIKE_MAX_RISE || drop > SPIKE_MAX_DROP) {
        isSpike = true;
        Serial.printf("SPIKE rejected: %.0f -> %.0f RPM\n", lastValidRPM, rawRPM);
      }
    }

    if (!isSpike) {
      lastValidRPM = rawRPM;
      displayRPM = (displayRPM == 0) ? rawRPM : (DISPLAY_FILTER_ALPHA * rawRPM + (1.0f - DISPLAY_FILTER_ALPHA) * displayRPM);
      controlRPM = (controlRPM == 0) ? rawRPM : (CONTROL_FILTER_ALPHA * rawRPM + (1.0f - CONTROL_FILTER_ALPHA) * controlRPM);
      if (displayRPM > maxRPM) maxRPM = displayRPM;
    }
  } else {
    displayRPM *= 0.95f;
    if (displayRPM < 10.0f) displayRPM = 0;
    controlRPM *= 0.97f;
    if (controlRPM < 10.0f) controlRPM = 0;
    lastValidRPM = 0;
  }

  currentRPM = displayRPM;
  isrSafeRPM = controlRPM;

  lastPulseCount      = curPulse;
  lastCalculationTime = currentTime;
}

// ============================================
// CLUTCH SENSOR
// ============================================
void checkClutchSensor() {
  unsigned long currentTime = millis();
  static unsigned long lastCheck = 0;
  if (currentTime - lastCheck < 50) return;
  lastCheck = currentTime;

  bool curClutch = (digitalRead(clutchSensorPin) == LOW);
  if (curClutch != lastClutchState) {
    clutchEngaged = curClutch;
    if (clutchEngaged) {
      launchControlDelayActive = false;
    } else {
      clutchReleaseTime = currentTime;
      bool _launchEn;
      bool _cancelWarmup = false;
      portENTER_CRITICAL(&dataMux);
      _launchEn = launchControlEnabled;
      // v12 FIX: Cancel pit limiter & auto warm up saat kopling dilepas
      if (pitLimiterEnabled) {
        pitLimiterEnabled = false;
        Serial.println("CLUTCH RELEASE: Pit Limiter dinonaktifkan.");
      }
      if (autoWarmUpEnabled) {
        autoWarmUpEnabled = false;
        warmUpActive      = false;
        _cancelWarmup     = true;
        Serial.println("CLUTCH RELEASE: Auto Warm Up dinonaktifkan.");
      }
      portEXIT_CRITICAL(&dataMux);
      if (_launchEn) launchControlDelayActive = true;
      // Restore DAC idle di luar mutex (I2C blocking call tidak boleh di dalam mutex)
      if (_cancelWarmup) {
        dac1.setVoltage(DAC_IDLE_AP1, false);
        dac2.setVoltage(DAC_IDLE_AP2, false);
      }
    }
    lastClutchState = curClutch;
  }

  if (launchControlDelayActive) {
    bool _launchEn;
    unsigned long _launchDelay;
    portENTER_CRITICAL(&dataMux);
    _launchEn    = launchControlEnabled;
    _launchDelay = launchControlDelay;
    portEXIT_CRITICAL(&dataMux);
    if (currentTime - clutchReleaseTime >= _launchDelay) {
      portENTER_CRITICAL(&dataMux);
      launchControlEnabled     = false;
      portEXIT_CRITICAL(&dataMux);
      launchControlDelayActive = false;
    }
  }
}

// ============================================
// ENGINE LIMITS CHECK
// FIX #1: Semua baca variabel shared pakai mutex di awal (copy ke lokal)
// ============================================
void checkEngineLimits() {
  // Snapshot semua shared variables dari Core 0 dengan mutex
  bool          _launchEnabled, _pitEnabled, _backfireEnabled;
  float         _launchLimit, _pitLimit, _backfireLimit, _softCutRange;
  unsigned long _pitPwmPeriod;
  float         _pitCutRatio;

  portENTER_CRITICAL(&dataMux);
  _launchEnabled  = launchControlEnabled;
  _launchLimit    = launchControlRPMLimit;
  _pitEnabled     = pitLimiterEnabled;
  _pitLimit       = pitLimiterRPMLimit;
  _pitCutRatio    = pitCutRatio;
  _pitPwmPeriod   = pitPwmPeriod;
  _backfireEnabled= backfireEnabled;
  _backfireLimit  = backfireRPMLimit;
  _softCutRange   = SOFT_CUT_RANGE;
  portEXIT_CRITICAL(&dataMux);

  launchControlActive = false;
  pitLimiterActive    = false;
  softCutActive       = false;
  hardCutActive       = false;
  backfireActive      = false;
  ignitionCutActive   = false;

  unsigned long currentTime = millis();

  // --- LAUNCH CONTROL ---
  if (_launchEnabled) {
    float softStart = _launchLimit - _softCutRange;

    if (controlRPM >= _launchLimit) {
      launchConfirmCounter++;
      if (launchConfirmCounter >= RPM_CONFIRM_COUNT) {
        launchControlActive = true;
        hardCutActive       = true;
        ignitionCutActive   = true;
        if (!hardCutLatch) {
          hardCutLatch     = true;
          hardCutStartTime = currentTime;
        }
      }
    } else if (controlRPM >= softStart) {
      launchConfirmCounter = 0;
      launchControlActive  = true;
      softCutActive        = true;
      ignitionCutActive    = true;
    } else {
      launchConfirmCounter = 0;
    }
  } else {
    launchConfirmCounter = 0;
  }

  // --- PIT LIMITER ---
  if (_pitEnabled && !launchControlActive) {
    const float PIT_SOFT_RANGE = 500.0f;
    float softStart = _pitLimit - PIT_SOFT_RANGE;

    if (controlRPM >= _pitLimit) {
      pitLimiterConfirmCounter++;
      if (pitLimiterConfirmCounter >= RPM_CONFIRM_COUNT) {
        pitLimiterActive  = true;
        hardCutActive     = true;
        ignitionCutActive = true;
      }
    } else if (controlRPM >= softStart) {
      pitLimiterConfirmCounter = 0;
      pitLimiterActive  = true;
      softCutActive     = true;
      ignitionCutActive = true;
    } else {
      pitLimiterConfirmCounter = 0;
      if (controlRPM < softStart - 100.0f) hardCutLatch = false;
    }
  } else if (!_pitEnabled) {
    pitLimiterConfirmCounter = 0;
  }

  // --- Hysteresis Launch Control latch ---
  if (_launchEnabled && hardCutLatch) {
    float releaseRPM = _launchLimit - HARD_CUT_HYSTERESIS;
    if (controlRPM <= releaseRPM) hardCutLatch = false;
    if (currentTime - hardCutStartTime >= HARD_CUT_SAFETY_MS) {
      hardCutLatch = false;
      Serial.println("HARD CUT: Safety timeout released.");
    }
  }

  // --- BACKFIRE ---
  float rpmDrop = prevRPMForBackfire - controlRPM;
  if (_backfireEnabled &&
      rpmDrop > 1500.0f &&
      controlRPM >= _backfireLimit &&
      (currentTime - lastBackfireTime > BACKFIRE_COOLDOWN)) {
    backfireActive    = true;
    ignitionCutActive = true;
    lastBackfireTime  = currentTime;
  }
  prevRPMForBackfire = controlRPM;

  // Simpan kembali variabel lokal yang berubah ke shared jika diperlukan
  // (tidak ada yang perlu ditulis balik dari checkEngineLimits)
}

// ============================================
// IGNITION CONTROL
// ============================================
bool          pitPwmOffPhase   = false;
unsigned long lastPitPwmToggle = 0;

void controlIgnition() {
  unsigned long currentTime = millis();

  if (timingKudaActive) { pulseCutStop(); return; }
  if (qsState == QS_CUTTING) { pulseCutStop(); return; }  // v28: biarkan controlIgnition saat cooldown

  // v29 SAFETY: kalau pulser mati (mesin mati/kabel lepas) pin jangan nyangkut di CUT
  static unsigned long lastSeenPulse   = 0;
  static unsigned long lastPulseChange = 0;
  unsigned long pc = pulseCount;
  if (pc != lastSeenPulse) { lastSeenPulse = pc; lastPulseChange = currentTime; }
  if (isrCutMode && (currentTime - lastPulseChange > 40)) {
    pulseCutStop();
    digitalWrite(ignitionPin, IGN_NORMAL);
    return;
  }

  if (backfireActive) {
    pulseCutStop();
    digitalWrite(ignitionPin, IGN_CUT);
    if (currentTime - lastBackfireTime > 50) backfireActive = false;
    return;
  }

  // --- LAUNCH CONTROL hard cut (latch): cut penuh ---
  if (hardCutActive && launchControlActive) {
    if (hardCutLatch) {
      pulseCutStop();
      digitalWrite(ignitionPin, IGN_CUT);
      return;
    }
  }

  // --- PIT LIMITER hard cut: pattern berbasis PULSE ---
  // pitPwmPeriod sekarang = JUMLAH PULSE per siklus (bukan ms)
  if (hardCutActive && pitLimiterActive) {
    uint32_t period = (uint32_t)pitPwmPeriod;
    uint32_t off    = (uint32_t)((pitCutRatio / 100.0f) * period + 0.5f);
    if (period - off < 2) off = period - 2;      // minimal 2 pulse ignition ON
    pulseCutStart(period, off);
    return;
  }

  // --- SOFT CUT (Pit zona 500 RPM & Launch zona SOFT_CUT_RANGE) ---
  if (softCutActive) {
    float activeLimit = 0;
    float softRange   = SOFT_CUT_RANGE;

    if (pitLimiterActive) {
      activeLimit = pitLimiterRPMLimit;
      softRange   = 500.0f;
    } else if (launchControlActive) {
      activeLimit = launchControlRPMLimit;
      softRange   = SOFT_CUT_RANGE;
    }

    if (activeLimit > 0) {
      float softStart = activeLimit - softRange;
      float ratio     = (controlRPM - softStart) / softRange;
      ratio           = constrain(ratio, 0.05f, 0.95f);
      uint32_t off    = (uint32_t)(ratio * SOFT_PERIOD_PULSES + 0.5f);
      pulseCutStart(SOFT_PERIOD_PULSES, off);
    } else {
      pulseCutStop();
      digitalWrite(ignitionPin, IGN_NORMAL);
    }
    return;
  }

  pulseCutStop();
  digitalWrite(ignitionPin, IGN_NORMAL);
}

// ============================================
// AUTO WARM UP
// v13 FIX: Skip penulisan DAC jika shift sedang berlangsung.
// Bug sebelumnya: saat warmup fase IDLE (!warmUpHighPhase), fungsi ini
// menulis DAC_IDLE SETELAH handleQuickShifter() menulis DAC_WARM_UP →
// throttle blip QS Down di-override → throttle tidak mau terbuka.
// ============================================
void handleAutoWarmUp() {
  // v28: Jangan sentuh DAC selama QS cutting atau cooldown
  if (qsState != QS_IDLE) return;
  unsigned long currentTime = millis();
  bool _autoWarmUpEnabled;
  portENTER_CRITICAL(&dataMux);
  _autoWarmUpEnabled = autoWarmUpEnabled;
  portEXIT_CRITICAL(&dataMux);

  if (_autoWarmUpEnabled) {
    if (!warmUpActive) {
      warmUpStartTime     = currentTime;
      warmUpActive        = true;
      warmUpLastCycleTime = currentTime;
      warmUpHighPhase     = false;
      dac1.setVoltage(DAC_IDLE_AP1, false);
      dac2.setVoltage(DAC_IDLE_AP2, false);
    }
    if (currentTime - warmUpStartTime >= warmUpDuration) {
      portENTER_CRITICAL(&dataMux);
      autoWarmUpEnabled = false;
      portEXIT_CRITICAL(&dataMux);
      warmUpActive = false;
      dac1.setVoltage(DAC_IDLE_AP1, false);
      dac2.setVoltage(DAC_IDLE_AP2, false);
      return;
    }
    if (!warmUpHighPhase) {
      if (currentTime - warmUpLastCycleTime >= warmUpIdleTime) {
        warmUpHighPhase     = true;
        warmUpLastCycleTime = currentTime;
        dac1.setVoltage(DAC_WARM_UP_AP1, false);
        dac2.setVoltage(DAC_WARM_UP_AP2, false);
      } else {
        dac1.setVoltage(DAC_IDLE_AP1, false);
        dac2.setVoltage(DAC_IDLE_AP2, false);
      }
    } else {
      if (currentTime - warmUpLastCycleTime >= warmUpRiseTime) {
        warmUpHighPhase     = false;
        warmUpLastCycleTime = currentTime;
        dac1.setVoltage(DAC_IDLE_AP1, false);
        dac2.setVoltage(DAC_IDLE_AP2, false);
      } else {
        dac1.setVoltage(DAC_WARM_UP_AP1, false);
        dac2.setVoltage(DAC_WARM_UP_AP2, false);
      }
    }
  } else if (warmUpActive) {
    warmUpActive = false;
    dac1.setVoltage(DAC_IDLE_AP1, false);
    dac2.setVoltage(DAC_IDLE_AP2, false);
  }
}

// ============================================
// TIMING KUDA
// ============================================
void handleTimingKuda() {
  unsigned long currentTime = millis();
  bool _timingKudaEnabled;
  portENTER_CRITICAL(&dataMux);
  _timingKudaEnabled = timingKudaEnabled;
  portEXIT_CRITICAL(&dataMux);

  timingKudaActive = (_timingKudaEnabled && controlRPM <= timingKudaRPMLimit &&
                      qsState == QS_IDLE && !pitLimiterActive);
  if (timingKudaActive) {
    if (currentTime - timingKudaLastCut >= timingKudaCutInterval) {
      digitalWrite(ignitionPin, IGN_CUT);
      timingKudaLastCut = currentTime;
    } else if (currentTime - timingKudaLastCut < timingKudaCutDuration) {
      digitalWrite(ignitionPin, IGN_CUT);
    } else {
      digitalWrite(ignitionPin, IGN_NORMAL);
    }
  } else if (_timingKudaEnabled && !pitLimiterActive && qsState == QS_IDLE) {
    digitalWrite(ignitionPin, IGN_NORMAL);
  }
}

// ============================================
// PHYSICAL BUTTON
// v12 FIX: Proper time-based debounce — DEBOUNCE_DELAY sebelumnya didefinisikan
// tapi tidak pernah dipakai. Getaran motor bisa picu false LOW → double-click
// palsu → pit limiter aktif sendiri. Sekarang pin harus stabil selama
// DEBOUNCE_DELAY ms sebelum press/release terdaftar.
// ============================================
void handlePhysicalButton() {
  unsigned long currentTime = millis();

  // Shadow state untuk debounce raw GPIO
  static unsigned long buttonRawLowSince  = 0;
  static unsigned long buttonRawHighSince = 0;
  static bool          buttonRawLow       = false;

  int rawState = digitalRead(physicalButtonPin);

  // Lacak kapan pin mulai stabil LOW atau HIGH
  if (rawState == LOW) {
    if (!buttonRawLow) {
      buttonRawLow      = true;
      buttonRawLowSince = currentTime;
    }
  } else {
    if (buttonRawLow) {
      buttonRawLow       = false;
      buttonRawHighSince = currentTime;
    }
  }

  // --- Debounced PRESS: pin LOW stabil selama DEBOUNCE_DELAY ---
  if (buttonRawLow && !buttonPressed &&
      (currentTime - buttonRawLowSince >= DEBOUNCE_DELAY)) {
    buttonPressed         = true;
    buttonPressTime       = currentTime;
    buttonLongPressActive = false;
  }

  // --- Debounced RELEASE: pin HIGH stabil selama DEBOUNCE_DELAY ---
  if (!buttonRawLow && buttonPressed &&
      (currentTime - buttonRawHighSince >= DEBOUNCE_DELAY)) {
    buttonPressed     = false;
    buttonReleaseTime = currentTime;
    unsigned long dur = buttonReleaseTime - buttonPressTime;

    if (dur < LONG_PRESS_TIME) {
      if (currentTime - lastClickTime < DOUBLE_CLICK_TIME) {
        buttonClickCount++;
      } else {
        buttonClickCount = 1;
      }
      lastClickTime = currentTime;

      if (buttonClickCount == 1) {
        portENTER_CRITICAL(&dataMux);
        launchControlEnabled = !launchControlEnabled;
        if (launchControlEnabled) {
          pitLimiterEnabled = false;
          autoWarmUpEnabled = false;
          warmUpActive      = false;
        } else {
          launchControlDelayActive = false;
        }
        portEXIT_CRITICAL(&dataMux);
      } else if (buttonClickCount == 2) {
        portENTER_CRITICAL(&dataMux);
        pitLimiterEnabled = !pitLimiterEnabled;
        if (pitLimiterEnabled) {
          launchControlEnabled = false;
          autoWarmUpEnabled    = false;
          warmUpActive         = false;
        }
        portEXIT_CRITICAL(&dataMux);
        buttonClickCount = 0;
      } else if (buttonClickCount >= 3) {
        buttonClickCount = 0;
      }
    }
  }

  // --- Long press ---
  if (buttonPressed && !buttonLongPressActive &&
      (currentTime - buttonPressTime >= LONG_PRESS_TIME)) {
    buttonLongPressActive = true;
    portENTER_CRITICAL(&dataMux);
    if (!autoWarmUpEnabled) {
      autoWarmUpEnabled    = true;
      launchControlEnabled = false;
      pitLimiterEnabled    = false;
    } else {
      autoWarmUpEnabled = false;
      warmUpActive      = false;
    }
    portEXIT_CRITICAL(&dataMux);
    if (!autoWarmUpEnabled) {
      dac1.setVoltage(DAC_IDLE_AP1, false);
      dac2.setVoltage(DAC_IDLE_AP2, false);
    }
  }

  if (currentTime - lastClickTime > DOUBLE_CLICK_TIME && buttonClickCount > 0) {
    buttonClickCount = 0;
  }
}

