String getSystemStatus() {
  if (qsState == QS_CUTTING)  return qsIsUpshift ? "QUICK SHIFT UP" : "QUICK SHIFT DOWN";
  if (qsState == QS_COOLDOWN) return "QS COOLDOWN";
  if (timingKudaActive)                           return "TIMING KUDA";
  if (hardCutActive && pitLimiterActive)          return "PIT LIMITER - HARD CUT";
  if (softCutActive && pitLimiterActive)          return "PIT LIMITER - SOFT CUT";
  if (warmUpActive)                               return warmUpHighPhase ? "WARM UP - HIGH" : "WARM UP - IDLE";
  if (hardCutActive && launchControlActive)       return "LAUNCH - HARD CUT";
  if (softCutActive && launchControlActive)       return "LAUNCH - SOFT CUT";
  if (launchControlDelayActive)                   return "LAUNCH DELAY";
  if (backfireActive)                             return "BACKFIRE";
  if (pitLimiterEnabled)                          return "PIT READY";
  if (launchControlEnabled)                       return "LAUNCH READY";
  if (autoWarmUpEnabled)                          return "WARM UP READY";
  if (timingKudaEnabled)                          return "TIMING KUDA READY";
  return "NORMAL";
}

