// v29: data mentah pulser untuk oscilloscope
// Format teks (dipisah spasi): now head count info ppr100 v0 v1 ... v(count-1)
//   info  = bit0 isrCutMode | (period<<8) | (offCount<<16)
//   v_i   = timestamp_us (bit0 = status ignition: 1 ON / 0 CUT), urut lama -> baru
static void handlePulserData() {
  uint32_t head = scopeHead;
  uint32_t now  = (uint32_t)esp_timer_get_time();
  uint32_t cnt  = 200;
  if (server.hasArg("since")) {
    uint32_t since = (uint32_t)strtoul(server.arg("since").c_str(), NULL, 10);
    cnt = head - since;
  }
  if (cnt > SCOPE_SEND_MAX) cnt = SCOPE_SEND_MAX;
  if (cnt > head) cnt = head;

  uint32_t info = (isrCutMode ? 1UL : 0UL) | ((isrPeriod & 0xFFUL) << 8) | ((isrOffCount & 0xFFUL) << 16);

  String out;
  out.reserve(48 + cnt * 11);
  out += (unsigned long)now;  out += ' ';
  out += (unsigned long)head; out += ' ';
  out += (unsigned long)cnt;  out += ' ';
  out += (unsigned long)info; out += ' ';
  out += (unsigned long)(PULSES_PER_REVOLUTION * 100.0f);
  for (uint32_t i = 0; i < cnt; i++) {
    uint32_t idx = (head - cnt + i) & (SCOPE_BUF - 1);
    out += ' ';
    out += (unsigned long)scopeBuf[idx];
  }
  server.sendHeader("Cache-Control", "no-store");
  server.send(200, "text/plain", out);
}

void handleRPMData() {
  StaticJsonDocument<2048> doc;

  // FIX #1: Snapshot semua shared variables dengan mutex
  bool  _launchEnabled, _pitEnabled, _backfireEnabled;
  bool  _warmUpEnabled, _timingKudaEnabled, _hotspotAutoOff;
  float _launchLimit, _pitLimit, _backfireLimit, _softCutRange, _pitCutRatio;
  unsigned long _launchDelay, _pitPwmPeriod;
  float _warmUpLimit, _timingKudaLimit;
  unsigned long _warmUpDuration, _warmUpRiseTime, _warmUpIdleTime;
  unsigned long _timingKudaCutDur, _timingKudaCutInt;
  bool  _hotspotActive;
  unsigned long _hotspotDeadline;

  portENTER_CRITICAL(&dataMux);
  _launchEnabled       = launchControlEnabled;
  _launchLimit         = launchControlRPMLimit;
  _launchDelay         = launchControlDelay;
  _pitEnabled          = pitLimiterEnabled;
  _pitLimit            = pitLimiterRPMLimit;
  _pitCutRatio         = pitCutRatio;
  _pitPwmPeriod        = pitPwmPeriod;
  _backfireEnabled     = backfireEnabled;
  _backfireLimit       = backfireRPMLimit;
  _warmUpEnabled       = autoWarmUpEnabled;
