  _warmUpRiseTime      = warmUpRiseTime;
  _warmUpIdleTime      = warmUpIdleTime;
  _timingKudaEnabled   = timingKudaEnabled;
  _timingKudaLimit     = timingKudaRPMLimit;
  _timingKudaCutDur    = timingKudaCutDuration;
  _timingKudaCutInt    = timingKudaCutInterval;
  _hotspotAutoOff      = hotspotAutoOffEnabled;
  _hotspotActive       = hotspotActive;
  _hotspotDeadline     = hotspotDeadline;
  _softCutRange        = SOFT_CUT_RANGE;
  portEXIT_CRITICAL(&dataMux);

  doc["rpm"]           = displayRPM;
  doc["controlRpm"]    = controlRPM;
  doc["maxRpm"]        = maxRPM;
  doc["systemStatus"]  = getSystemStatus();
  doc["clutchEngaged"] = clutchEngaged;
  doc["ignitionCut"]   = ignitionCutActive;

  doc["launchControlEnabled"]  = _launchEnabled;
  doc["launchControlActive"]   = launchControlActive;
  doc["launchControlSoftCut"]  = softCutActive && _launchEnabled;
  doc["launchControlHardCut"]  = hardCutActive && _launchEnabled;
  doc["launchControlLimit"]    = _launchLimit;
  doc["launchControlDelay"]    = _launchDelay;

  doc["pitLimiterEnabled"]     = _pitEnabled;
  doc["pitLimiterActive"]      = pitLimiterActive;
  doc["pitLimiterSoftCut"]     = softCutActive && _pitEnabled;
  doc["pitLimiterHardCut"]     = hardCutActive && _pitEnabled;
  doc["pitLimiterLimit"]       = _pitLimit;
  doc["pitCutRatio"]           = _pitCutRatio;
  doc["pitPwmPeriod"]          = _pitPwmPeriod;
  doc["pitPwmOffMs"]           = (unsigned long)((_pitCutRatio / 100.0f) * _pitPwmPeriod);
  doc["pitPwmOnMs"]            = _pitPwmPeriod - (unsigned long)((_pitCutRatio / 100.0f) * _pitPwmPeriod);

  doc["backfireEnabled"]       = _backfireEnabled;
  doc["backfireActive"]        = backfireActive;
  doc["backfireRPMLimit"]      = _backfireLimit;

  doc["quickShifterEnabled"]            = quickShifterEnabled;
  doc["quickshifterActive"]             = (qsState != QS_IDLE);
  doc["quickshifterState"]              = (qsState == QS_CUTTING) ? "CUTTING" : (qsState == QS_COOLDOWN) ? "COOLDOWN" : "IDLE";
  doc["quickshifterUpEnabled"]          = quickShifterUpEnabled;
  doc["quickshifterDownEnabled"]        = quickShifterDownEnabled;
  doc["quickshifterMinRPM"]             = quickShifterMinRPM;
  doc["quickshifterCooldownTime"]       = quickShifterCooldownTime;
  doc["quickshifterCutTime3000"]        = quickShifterCutTime3000;
  doc["quickshifterCutTime6000"]        = quickShifterCutTime6000;
  doc["quickshifterCutTime9000"]        = quickShifterCutTime9000;
  doc["quickshifterCutTime12000"]       = quickShifterCutTime12000;
  doc["quickshifterDownshiftDuration"]  = quickShifterDownshiftDuration;

  doc["autoWarmUpEnabled"]     = _warmUpEnabled;
  doc["warmUpActive"]          = warmUpActive;
  doc["warmUpRPMLimit"]        = _warmUpLimit;
  doc["warmUpDuration"]        = _warmUpDuration;
  doc["warmUpRiseTime"]        = _warmUpRiseTime;
  doc["warmUpIdleTime"]        = _warmUpIdleTime;

  doc["timingKudaEnabled"]     = _timingKudaEnabled;
  doc["timingKudaActive"]      = timingKudaActive;
  doc["timingKudaRPMLimit"]    = _timingKudaLimit;
  doc["timingKudaCutDuration"] = _timingKudaCutDur;
  doc["timingKudaCutInterval"] = _timingKudaCutInt;

  doc["hotspotActive"]         = _hotspotActive;
  doc["hotspotAutoOffEnabled"] = _hotspotAutoOff;
  doc["softCutRange"]          = _softCutRange;

  if (_hotspotActive && _hotspotAutoOff) {
    unsigned long now = millis();
    long rem = (long)(_hotspotDeadline) - (long)now;
    doc["hotspotRemainingTime"] = rem > 0 ? rem : 0;
  } else {
    doc["hotspotRemainingTime"] = 0;
  }

  String response;
  serializeJson(doc, response);
  server.send(200, "application/json", response);
}

