// ============================================
// QUICK SHIFTER TEST HANDLERS — v18
// Trigger shift dari web UI tanpa sensor fisik.
// Langsung set qsState = QS_CUTTING seperti yang dilakukan ISR.
// ============================================
void handleTestQSUp() {
  if (!quickShifterEnabled) {
    server.send(200, "application/json", "{\"status\":\"error\",\"message\":\"Quick Shifter tidak aktif\"}");
    return;
  }
  if (qsState != QS_IDLE) {
    server.send(200, "application/json", "{\"status\":\"error\",\"message\":\"Shift sedang berlangsung\"}");
    return;
  }
  unsigned long cutMs = quickShifterCutTime3000;
  if      (controlRPM >= 12000) cutMs = quickShifterCutTime12000;
  else if (controlRPM >= 9000)  cutMs = quickShifterCutTime9000;
  else if (controlRPM >= 6000)  cutMs = quickShifterCutTime6000;

  qsIsUpshift  = true;
  qsCutStartMs = millis();
  qsDacWritten = false;
  qsState      = QS_CUTTING;

  String resp = "{\"status\":\"success\",\"cutMs\":" + String(cutMs) + "}";
  server.send(200, "application/json", resp);
}

void handleTestQSDown() {
  if (!quickShifterEnabled) {
    server.send(200, "application/json", "{\"status\":\"error\",\"message\":\"Quick Shifter tidak aktif\"}");
    return;
  }
  if (qsState != QS_IDLE) {
    server.send(200, "application/json", "{\"status\":\"error\",\"message\":\"Shift sedang berlangsung\"}");
    return;
  }
  qsIsUpshift  = false;
  qsCutStartMs = millis();
  qsDacWritten = false;
  qsState      = QS_CUTTING;

  String resp = "{\"status\":\"success\",\"durationMs\":" + String(quickShifterDownshiftDuration) + "}";
  server.send(200, "application/json", resp);
}

// ============================================
// OTA FIRMWARE UPDATE HANDLER — v21
// Upload via HTTP POST multipart/form-data ke /ota-update
// Endpoint ini hanya aktif saat hotspot menyala.
// Motor HARUS dimatikan sebelum OTA — jangan update saat motor jalan.
// ============================================
void handleOTAUpdate() {
  // Tolak request kalau bukan POST
  if (server.method() != HTTP_POST) {
    server.send(405, "text/plain", "Method Not Allowed");
    return;
  }

  // Cek apakah ada file yang diupload
  if (!server.hasArg("plain") && server.upload().totalSize == 0) {
    server.send(400, "text/plain", "Tidak ada file firmware");
    return;
  }

  // Response sukses sudah dikirim oleh onFileUpload handler
  // Ini hanya fallback jika upload handler tidak bekerja
  server.send(200, "text/plain", "OK");

  Serial.println("OTA: Update selesai, restart dalam 1 detik...");
  delay(1000);
  ESP.restart();
}

// Upload handler — dipanggil streaming saat data masuk
void handleOTAUpload() {
  HTTPUpload& upload = server.upload();

  if (upload.status == UPLOAD_FILE_START) {
    Serial.printf("OTA: Mulai upload: %s  size=%u bytes\n", upload.filename.c_str(), upload.totalSize);

    // Hentikan motor task sementara agar tidak ada akses hardware bersamaan
    // (Motor task akan berhenti sendiri saat restart)

    if (!Update.begin(UPDATE_SIZE_UNKNOWN)) {
      Update.printError(Serial);
      Serial.println("OTA: begin() gagal");
    }

  } else if (upload.status == UPLOAD_FILE_WRITE) {
    if (Update.write(upload.buf, upload.currentSize) != upload.currentSize) {
      Update.printError(Serial);
      Serial.println("OTA: write() gagal");
    } else {
      Serial.printf("OTA: Written %u / %u bytes (%.0f%%)\n",
        upload.totalSize, upload.totalSize,
        upload.totalSize > 0 ? (100.0f * upload.totalSize / upload.totalSize) : 0);
    }

  } else if (upload.status == UPLOAD_FILE_END) {
    if (Update.end(true)) {
      Serial.printf("OTA: Update selesai! Total %u bytes. Restart...\n", upload.totalSize);
      server.send(200, "text/plain", "Update berhasil! ESP32 akan restart.");
      delay(500);
      ESP.restart();
    } else {
      Update.printError(Serial);
      server.send(500, "text/plain", "Update gagal: " + String(Update.errorString()));
    }

  } else if (upload.status == UPLOAD_FILE_ABORTED) {
    Update.abort();
    Serial.println("OTA: Upload dibatalkan.");
    server.send(400, "text/plain", "Upload dibatalkan");
  }
}

// ============================================
// SETUP
// ============================================
void setup() {
  Serial.begin(115200);
  delay(500);
  Serial.println("=== CBR250RR Control System V29 ===");

  loadConfig();

  pinMode(pulserPin,           INPUT_PULLUP);
  pinMode(ignitionPin,         OUTPUT);
  pinMode(clutchSensorPin,     INPUT_PULLUP);
  pinMode(quickShifterUpPin,   INPUT_PULLUP);
  pinMode(quickShifterDownPin, INPUT_PULLUP);
  pinMode(physicalButtonPin,   INPUT_PULLUP);

  // v28: QS tidak pakai prev state — polling langsung
  // Tunggu 50ms agar PULLUP stabil sebelum motor task jalan
  delay(50);

  digitalWrite(ignitionPin, IGN_NORMAL);

  attachInterrupt(digitalPinToInterrupt(pulserPin), pulseInterrupt, RISING);
  // QS tidak pakai ISR — sensor dibaca via polling di handleQuickShifter()

  dac1.begin(0x60);
  dac2.begin(0x61);
  dac1.setVoltage(DAC_IDLE_AP1, false);
  dac2.setVoltage(DAC_IDLE_AP2, false);

  WiFi.mode(WIFI_AP);
  IPAddress local_IP(192,168,4,1);
  IPAddress gateway(192,168,4,1);
  IPAddress subnet(255,255,255,0);
  WiFi.softAPConfig(local_IP, gateway, subnet);
  WiFi.softAP(ssid, password);
  Serial.print("AP IP: ");
  Serial.println(WiFi.softAPIP());

  hotspotDeadline        = millis() + 60000UL;  // v14: deadline 60s dari sekarang
  hotspotActive          = true;

  server.on("/",                        handleRoot);
  server.on("/rpm-data",                handleRPMData);
  server.on("/pulser-data",             handlePulserData);
  server.on("/reset-max",               handleResetMax);
  server.on("/toggle-launch",           handleToggleLaunch);
  server.on("/toggle-pit",              handleTogglePit);
  server.on("/toggle-backfire",         handleToggleBackfire);
  server.on("/toggle-quickshifter",     handleToggleQuickShifter);
  server.on("/toggle-warmup",           handleToggleAutoWarmUp);
  server.on("/toggle-timingkuda",       handleToggleTimingKuda);
  server.on("/add-hotspot-time",        handleAddHotspotTime);
  server.on("/force-hotspot-off",       handleForceHotspotOff);
  server.on("/toggle-hotspot",          handleToggleHotspot);
  server.on("/disable-all",             handleDisableAll);
  server.on("/save-settings",           handleSaveSettings);
  server.on("/set-launch-rpm",          handleSetLaunchRPM);
  server.on("/set-launch-delay",        handleSetLaunchDelay);
  server.on("/set-pit-rpm",             handleSetPitRPM);
  server.on("/set-pit-cut-ratio",       handleSetPitCutRatio);
  server.on("/set-pit-pwm-period",      handleSetPitPwmPeriod);
  server.on("/set-backfire-rpm",        handleSetBackfireRPM);
  server.on("/set-quickshifter-minrpm",             handleSetQuickShifterMinRPM);
  server.on("/set-quickshifter-cooldown",           handleSetQuickShifterCooldown);
  server.on("/set-quickshifter-up",                 handleSetQuickShifterUp);
  server.on("/set-quickshifter-down",               handleSetQuickShifterDown);
  server.on("/set-quickshifter-cut-3000",           handleSetQuickShifterCut3000);
  server.on("/set-quickshifter-cut-6000",           handleSetQuickShifterCut6000);
  server.on("/set-quickshifter-cut-9000",           handleSetQuickShifterCut9000);
  server.on("/set-quickshifter-cut-12000",          handleSetQuickShifterCut12000);
  server.on("/set-quickshifter-downshift-duration", handleSetQuickShifterDownshiftDuration);
  server.on("/set-warmup-rpm",          handleSetWarmUpRPM);
  server.on("/set-warmup-duration",     handleSetWarmUpDuration);
  server.on("/set-warmup-risetime",     handleSetWarmUpRiseTime);
  server.on("/set-warmup-idletime",     handleSetWarmUpIdleTime);
  server.on("/set-timingkuda-rpm",      handleSetTimingKudaRPM);
  server.on("/set-timingkuda-cut",      handleSetTimingKudaCut);
  server.on("/set-timingkuda-interval", handleSetTimingKudaInterval);
  server.on("/set-softcut-range",       handleSetSoftCutRange);
  server.on("/test-qs-up",              handleTestQSUp);
  server.on("/test-qs-down",            handleTestQSDown);

  // OTA update endpoint — upload via multipart POST
  server.on("/ota-update", HTTP_POST,
    handleOTAUpdate,    // response handler (dipanggil setelah upload selesai)
    handleOTAUpload     // upload handler (dipanggil streaming saat data masuk)
  );

  server.begin();
  Serial.println("Web server started. System READY.");
  lastCalculationTime = millis();

  xTaskCreatePinnedToCore(wifiTask,  "WiFiTask",  4096, NULL, 1, NULL, 0);
  xTaskCreatePinnedToCore(motorTask, "MotorTask", 8192, NULL, 2, NULL, 1);

  Serial.println("FreeRTOS Tasks spawned. Core 0 = WiFi, Core 1 = Motor.");
}

// ============================================
// FREERTOS TASKS
// ============================================

// Core 0 — WiFi & Web Server
void wifiTask(void* pvParameters) {
  Serial.print("WiFi Task running on Core ");
  Serial.println(xPortGetCoreID());

  for (;;) {
    bool _pending, _hotspotActive, _autoOff;
    unsigned long _deadline;

    portENTER_CRITICAL(&dataMux);
    _pending       = pendingDisconnect;
    _hotspotActive = hotspotActive;
    _autoOff       = hotspotAutoOffEnabled;
    _deadline      = hotspotDeadline;
    portEXIT_CRITICAL(&dataMux);

    if (_pending) {
      server.stop();
      WiFi.softAPdisconnect(true);
      portENTER_CRITICAL(&dataMux);
      hotspotActive   = false;
      pendingDisconnect = false;
      portEXIT_CRITICAL(&dataMux);
      Serial.println("HOTSPOT: Disconnected safely (Core 0).");
    }

    if (_hotspotActive && !_pending) {
      server.handleClient();
    }

    // v14 FIX: Bandingkan millis() langsung dengan deadline
    if (_autoOff && _hotspotActive && !_pending) {
      if (millis() >= _deadline) {
        Serial.println("HOTSPOT: Deadline reached, shutting down.");
        portENTER_CRITICAL(&dataMux);
        pendingDisconnect = true;
        portEXIT_CRITICAL(&dataMux);
      }
    }

    vTaskDelay(1 / portTICK_PERIOD_MS);
  }
}

// Core 1 — Motor Control
void motorTask(void* pvParameters) {
  Serial.print("Motor Task running on Core ");
  Serial.println(xPortGetCoreID());

  for (;;) {
    // QS polling tidak butuh shadow variables — config dibaca langsung di handleQuickShifter()
    calculateRPM();
    checkClutchSensor();
    checkEngineLimits();
    controlIgnition();
    handleQuickShifter();
    handleAutoWarmUp();
    handleTimingKuda();
    handlePhysicalButton();

    // FIX #5: vTaskDelay 1ms — cukup responsif untuk motor, cegah watchdog
    vTaskDelay(1 / portTICK_PERIOD_MS);
  }
}

void loop() {
  vTaskDelete(NULL);
}
